values
  ('egg-fried-rice', 'Egg Fried Rice', 'The ultimate leftover-rice rescue: fluffy egg, sweet peas and soy in one pan.', '🍳', 5, 10, 15, 1,
   1.10, 'Easy', array['lunch', 'dinner'], array['budget', 'one-pan', 'quick', 'vegetarian'], array['wok or large frying pan'],
   array['Heat the oil in a wok or large frying pan over medium-high heat.', 'Add the peas and the white parts of the spring onions and stir-fry for 2 minutes.', 'Push everything to one side, crack in the eggs and scramble until fully set.', 'Add the cold cooked rice, breaking up any clumps, and stir-fry for 3-4 minutes until piping hot all the way through.', 'Stir through the soy sauce and finish with the green parts of the spring onions.'],
   'Use cooked rice that was cooled quickly, kept in the fridge and is no more than 24 hours old. Eat the fried rice straight away.'),
  ('tomato-garlic-spaghetti', 'Tomato & Garlic Spaghetti', 'A cheap, cosy pantry pasta with a rich tomato sauce that cooks while the pasta boils.', '🍝', 5, 15, 20, 2,
   0.80, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'quick', 'vegetarian'], array['large pot', 'frying pan', 'colander'],
   array['Bring a large pot of salted water to the boil and cook the pasta according to the packet.', 'Meanwhile, finely chop the onion and garlic. Soften the onion in the olive oil in a frying pan over medium heat for 5 minutes.', 'Add the garlic and cook for 1 minute, then pour in the canned tomatoes. Simmer for 10 minutes, stirring now and then, and season with salt.', 'Reserve a splash of pasta water, drain the pasta and toss it through the sauce, loosening with the pasta water if needed. Top with parmesan if using.'],
   null),
  ('cheesy-veggie-omelette', 'Cheesy Veggie Omelette', 'Ready in 10 minutes and perfect between lectures.', '🥚', 3, 7, 10, 1,
   1.20, 'Easy', array['breakfast', 'lunch'], array['budget', 'high-protein', 'quick', 'vegetarian'], array['non-stick frying pan', 'bowl', 'whisk or fork'],
   array['Beat the eggs with a pinch of salt and pepper.', 'Dice the tomato. Heat the oil in a non-stick frying pan over medium heat and wilt the spinach for 1 minute.', 'Pour in the eggs and tilt the pan to spread them. Cook for 2 minutes, gently pulling the set edges towards the centre.', 'When the top is almost set, scatter over the tomato and cheese, fold in half and cook for 1-2 more minutes until the egg is set.'],
   null),
  ('chickpea-spinach-curry', 'Chickpea & Spinach Curry', 'Creamy coconut curry that makes great leftovers for tomorrow''s lunch.', '🍛', 5, 20, 25, 2,
   1.40, 'Easy', array['dinner'], array['meal-prep', 'vegan', 'vegetarian'], array['large frying pan or pot', 'saucepan'],
   array['Start cooking the rice in a saucepan according to the packet instructions.', 'Chop the onion and garlic and fry in the oil over medium heat for 5 minutes until soft.', 'Stir in the curry powder and cook for 30 seconds until fragrant.', 'Add the drained chickpeas and the coconut milk, then simmer for 10 minutes until slightly thickened.', 'Stir in the spinach until wilted, season with salt and serve over the rice.'],
   'Cool within 2 hours and refrigerate. Eat the curry within 2 days and the rice within 24 hours, reheating until piping hot.'),
  ('black-bean-quesadillas', 'Black Bean Quesadillas', 'Crispy, melty and filling, with beans, pepper and plenty of cheese.', '🌮', 5, 10, 15, 1,
   1.60, 'Easy', array['lunch', 'dinner'], array['quick', 'vegetarian'], array['frying pan', 'fork'],
   array['Finely dice the pepper and roughly mash the drained beans with a fork.', 'Spread the beans over one half of each tortilla, top with the pepper and cheese, then fold in half.', 'Heat a dry or very lightly oiled frying pan over medium heat.', 'Cook the quesadillas for 2-3 minutes per side until golden and the cheese has melted. Cut into wedges and serve with salsa if you like.'],
   null),
  ('tuna-pasta-salad', 'Lemony Tuna Pasta Salad', 'A fresh make-ahead lunch that keeps for two days in the fridge.', '🥗', 10, 10, 20, 2,
   1.30, 'Easy', array['lunch'], array['fresh', 'high-protein', 'meal-prep', 'quick'], array['pot', 'colander', 'large bowl'],
   array['Cook the pasta in a pot of boiling salted water according to the packet, then drain and rinse under cold water to cool.', 'Dice the cucumber and tomatoes.', 'Whisk the lemon juice with the olive oil and a pinch of salt and pepper.', 'Toss the pasta, drained tuna, vegetables and dressing together.'],
   'Refrigerate in a sealed container within 2 hours of cooking and eat within 2 days.'),
  ('overnight-oats', 'Overnight Oats', 'Five minutes the night before means breakfast is waiting for your 9am. Needs at least 4 hours to soak.', '🥣', 5, 0, 5, 1,
   0.60, 'Easy', array['breakfast'], array['budget', 'meal-prep', 'no-cook', 'quick', 'vegetarian'], array['jar or container with a lid'],
   array['In a jar or container, mix the oats, milk and yogurt.', 'Stir in the honey, cover and refrigerate overnight (at least 4 hours).', 'In the morning, stir and add a splash more milk if it is too thick. Top with berries if using. Eat cold, or warm in the microwave for 1-2 minutes.'],
   'Keep covered in the fridge and eat within 2 days.'),
  ('peanut-butter-banana-toast', 'Peanut Butter Banana Toast', 'Sweet, salty and satisfying fuel for a long study session.', '🍌', 2, 3, 5, 1,
   0.50, 'Easy', array['breakfast', 'snack'], array['budget', 'quick', 'vegetarian'], array['knife'],
   array['Toast the bread.', 'Spread the peanut butter on the warm toast.', 'Slice the banana on top and finish with a drizzle of honey if you like.'],
   null),
  ('shakshuka', 'Easy Shakshuka', 'Eggs gently cooked in a spiced pepper and tomato sauce. Brunch hero.', '🍅', 5, 20, 25, 2,
   1.10, 'Easy', array['breakfast', 'lunch', 'dinner'], array['budget', 'one-pan', 'vegetarian'], array['wide frying pan with a lid'],
   array['Slice the onion and pepper and fry in the oil in a wide frying pan over medium heat for 6-8 minutes until soft.', 'Add the chopped garlic, plus the cumin and paprika if using, and cook for 1 minute.', 'Pour in the canned tomatoes, season with salt and simmer for 5 minutes until slightly thickened.', 'Make 4 small wells in the sauce and crack an egg into each. Cover and cook on low heat for 6-8 minutes until the whites are completely set.', 'Serve straight from the pan, with bread for dipping if you have some.'],
   null),
  ('lemon-garlic-chicken-rice', 'Lemon Garlic Chicken & Rice', 'Juicy chicken strips in a zesty garlic pan sauce over fluffy rice.', '🍗', 10, 20, 30, 2,
   2.20, 'Easy', array['dinner'], array['high-protein'], array['frying pan', 'saucepan', 'separate chopping board for raw meat'],
   array['Cook the rice in a saucepan according to the packet instructions.', 'Slice the chicken into strips on a separate board and season with salt and pepper. Wash your hands and the board after handling raw chicken.', 'Heat the oil in a frying pan over medium-high heat and cook the chicken for 6-8 minutes, turning, until golden and cooked through with no pink in the middle (75°C if you have a thermometer).', 'Lower the heat, add the sliced garlic and cook for 1 minute, then squeeze over the lemon juice and stir to coat.', 'Serve over the rice with the pan juices spooned on top.'],
   null),
  ('red-lentil-soup', 'Red Lentil & Tomato Soup', 'Hearty, freezer-friendly and costs less than a coffee per bowl.', '🥕', 10, 25, 35, 3,
   0.60, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'meal-prep', 'vegan', 'vegetarian'], array['large pot'],
   array['Chop the onion, carrots and garlic and soften in the oil in a large pot over medium heat for 5 minutes.', 'Add the rinsed lentils, canned tomatoes and 900 ml water (crumble in the stock cube if using) and bring to the boil.', 'Simmer for 20 minutes, stirring occasionally, until the lentils are completely soft.', 'Season with salt. Blend part of the soup with a blender for a creamier texture, or leave it chunky.'],
   'Cool within 2 hours, then refrigerate and eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('sheet-pan-sweet-potato-chickpeas', 'Sheet-Pan Sweet Potato & Chickpeas', 'Throw it all on one tray and study while the oven does the work.', '🍠', 10, 30, 40, 2,
   1.20, 'Easy', array['dinner'], array['air-fryer', 'budget', 'one-pan', 'vegan', 'vegetarian'], array['baking tray'],
   array['Preheat the oven to 200°C (180°C fan).', 'Cut the sweet potatoes into 2 cm cubes and the pepper and onion into chunks. Drain the chickpeas and pat them dry.', 'Toss everything on a baking tray with the oil, salt and paprika if using.', 'Roast for 25-30 minutes, turning halfway, until the sweet potato is tender and the chickpeas are crisp.'],
   null),
  ('quick-mushroom-risotto', 'Quick Mushroom Risotto', 'Creamy, comforting and surprisingly cheap. Worth the stirring.', '🍄', 5, 30, 35, 2,
   1.80, 'Medium', array['dinner'], array['comfort', 'vegetarian'], array['large frying pan or pot', 'saucepan', 'ladle'],
   array['Keep about 750 ml of hot water (with the stock cube dissolved in it, if using) in a saucepan over low heat.', 'Fry the chopped onion in the oil for 4 minutes, then add the sliced mushrooms and garlic and cook for 4 minutes more.', 'Add the rice and stir for 1 minute to coat it in the oil.', 'Add a ladle of hot liquid at a time, stirring often and waiting until it is mostly absorbed before adding more. Continue for 18-20 minutes until the rice is creamy and just tender.', 'Take off the heat, stir in the butter and grated parmesan, season with salt and rest for 1 minute.'],
   null),
  ('veggie-noodle-stir-fry', 'Veggie Noodle Stir-Fry', 'Faster than delivery and a lot cheaper. Crunchy veg, glossy noodles.', '🍜', 5, 10, 15, 1,
   1.30, 'Easy', array['lunch', 'dinner'], array['quick', 'vegan', 'vegetarian'], array['wok or large frying pan', 'saucepan'],
   array['Cook the noodles in a saucepan according to the packet, then drain and rinse briefly.', 'Cut the carrot and pepper into thin strips and slice the garlic.', 'Stir-fry the vegetables in the oil in a wok over high heat for 3-4 minutes until just tender, adding the garlic for the final 30 seconds.', 'Add the noodles and soy sauce and toss for 1-2 minutes until hot and glossy.'],
   null),
  ('greek-salad', 'Classic Greek Salad', 'No cooking, big flavour. Great with bread on a hot day.', '🥒', 10, 0, 10, 1,
   1.90, 'Easy', array['lunch'], array['fresh', 'no-cook', 'quick', 'vegetarian'], array['knife', 'chopping board', 'bowl'],
   array['Chop the tomatoes and cucumber into chunks and thinly slice the onion.', 'Combine in a bowl with the olives if using, and season lightly with salt (the feta is already salty).', 'Place the feta on top, drizzle with olive oil and sprinkle with oregano if you have it.'],
   null),
  ('avocado-egg-toast', 'Avocado & Egg Toast', 'The café classic for a fraction of the price.', '🥑', 3, 7, 10, 1,
   1.40, 'Easy', array['breakfast'], array['quick', 'vegetarian'], array['frying pan', 'fork'],
   array['Toast the bread in a toaster, or in a dry frying pan over medium heat for 1-2 minutes per side.', 'Fry the egg in the oil in a frying pan over medium heat for 3-4 minutes, until the white is fully set.', 'Mash the avocado with a pinch of salt and spread it on the toast.', 'Top with the egg, a crack of black pepper and chilli flakes if you like.'],
   null),
  ('spanish-potato-omelette', 'Spanish Potato Omelette', 'Tortilla de patatas: three ingredients, endless student dinners.', '🥔', 10, 30, 40, 3,
   0.70, 'Medium', array['lunch', 'dinner'], array['budget', 'meal-prep', 'vegetarian'], array['non-stick frying pan', 'large plate', 'large bowl'],
   array['Peel and thinly slice the potatoes and onion.', 'Cook them gently in the olive oil in a non-stick frying pan over medium-low heat, covered, for 15-20 minutes, stirring occasionally, until very soft but not browned.', 'Beat the eggs with salt in a large bowl. Drain the potatoes and onion (save the oil), fold them into the eggs and leave for 5 minutes.', 'Heat 1 tbsp of the saved oil in the pan, pour in the mixture and cook on medium-low for 5-6 minutes until mostly set.', 'Place a large plate over the pan, flip carefully, slide the omelette back in and cook for 3-4 minutes more until set in the middle.'],
   'Cool, then cover and refrigerate within 2 hours. Eat within 2 days, cold or reheated until piping hot.'),
  ('chorizo-chickpea-stew', 'Chorizo & Chickpea Stew', 'Smoky, warming one-pot stew inspired by Spanish home cooking.', '🍲', 5, 20, 25, 2,
   1.50, 'Easy', array['dinner'], array['comfort', 'meal-prep', 'one-pan'], array['deep frying pan or pot'],
   array['Dice the chorizo, onion and garlic.', 'Fry the chorizo in the oil over medium heat for 3 minutes until it releases its red oil, then add the onion and cook for 5 minutes.', 'Add the garlic (and paprika if using) for 1 minute, then stir in the drained chickpeas and canned tomatoes.', 'Simmer for 12-15 minutes until thickened and the chorizo is cooked through. Season to taste and serve with bread.'],
   'Cool within 2 hours, refrigerate and eat within 2 days. Reheat until piping hot.'),
  ('pasta-peas-ham', 'Pasta with Peas & Ham', 'A 15-minute comfort bowl made from fridge odds and ends.', '🥓', 3, 12, 15, 1,
   1.30, 'Easy', array['lunch', 'dinner'], array['comfort', 'quick'], array['pot', 'colander'],
   array['Cook the pasta in a pot of boiling salted water, adding the frozen peas for the final 3 minutes.', 'Chop the ham into bite-sized pieces.', 'Reserve a splash of pasta water, drain, then return everything to the pot with the oil, ham, grated parmesan and a little pasta water. Stir until glossy.'],
   null),
  ('loaded-jacket-potato', 'Loaded Microwave Jacket Potato', 'No oven needed. A filling dorm-friendly dinner in 15 minutes.', '🥔', 2, 13, 15, 1,
   1.10, 'Easy', array['lunch', 'dinner'], array['budget', 'quick', 'vegetarian'], array['microwave-safe plate', 'fork'],
   array['Prick the potato all over with a fork. Microwave on high for 8-10 minutes, turning halfway, until soft all the way to the centre.', 'Meanwhile, warm the drained beans in the microwave for 1 minute with a pinch of salt, stirring halfway.', 'Carefully split the potato open (it will be very hot), fluff up the inside and season with salt.', 'Top with the beans, cheese, a spoonful of yogurt and spring onion if using. Microwave for 30 seconds more to melt the cheese if you like.'],
   null),
  ('coconut-lentil-dal', 'Coconut Lentil Dal', 'Silky, gently spiced lentils. Cheap, filling and freezes brilliantly.', '🥥', 10, 25, 35, 3,
   0.80, 'Easy', array['dinner'], array['budget', 'comfort', 'meal-prep', 'vegan', 'vegetarian'], array['large pot', 'grater'],
   array['Finely chop the onion and garlic, grate the ginger, and fry in the oil in a large pot over medium heat for 5 minutes.', 'Stir in the curry powder and cook for 30 seconds.', 'Add the rinsed lentils, coconut milk and 400 ml water. Simmer for 20 minutes, stirring often so nothing sticks, until the lentils break down.', 'Season with salt and add a splash of water if it is too thick. Serve with rice or bread.'],
   'Cool within 2 hours, refrigerate and eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('zucchini-feta-pasta', 'Zucchini & Feta Pasta', 'Bright, lemony and light, with salty feta crumbled on top.', '🍋', 5, 15, 20, 2,
   1.40, 'Easy', array['lunch', 'dinner'], array['fresh', 'quick', 'vegetarian'], array['pot', 'frying pan', 'grater'],
   array['Cook the pasta in a pot of boiling salted water according to the packet.', 'Meanwhile, grate or thinly slice the zucchini and fry it in the oil in a frying pan over medium-high heat for 5 minutes until soft and lightly golden. Add the garlic for 1 minute.', 'Drain the pasta, reserving a splash of water, and toss it with the zucchini, lemon juice and pasta water.', 'Crumble the feta over the top and season with black pepper.'],
   null),
  ('banana-oat-pancakes', 'Banana Oat Pancakes', 'Three-ingredient pancakes with no flour and no added sugar.', '🥞', 5, 10, 15, 1,
   0.60, 'Easy', array['breakfast'], array['budget', 'quick', 'vegetarian'], array['non-stick frying pan', 'bowl', 'fork'],
   array['Mash the banana until smooth, whisk in the eggs and stir in the oats. Rest for 2 minutes to thicken.', 'Heat a lightly oiled non-stick frying pan over medium-low heat.', 'Spoon in small pancakes and cook for about 2 minutes per side until golden and set in the middle. Serve with honey if you like.'],
   null),
  ('chicken-salad-wrap', 'Chicken Salad Wraps', 'Fresh wraps with golden chicken and a quick yogurt sauce.', '🌯', 10, 10, 20, 2,
   2.10, 'Easy', array['lunch'], array['fresh', 'high-protein', 'quick'], array['frying pan', 'separate chopping board for raw meat'],
   array['Slice the chicken into thin strips on a separate board and season with salt and pepper. Wash your hands and the board afterwards.', 'Cook in the oil in a frying pan over medium-high heat for 6-8 minutes until cooked through with no pink inside.', 'Shred the lettuce and slice the tomato. Mix the yogurt with a pinch of salt and pepper for a quick sauce.', 'Warm the tortillas briefly in the dry pan, fill with lettuce, tomato, chicken and yogurt sauce, and roll up tightly.'],
   null),
  ('garlic-mushrooms-on-toast', 'Garlic Mushrooms on Toast', 'Buttery, savoury and ready in about 12 minutes.', '🍞', 4, 8, 12, 1,
   1.20, 'Easy', array['breakfast', 'lunch'], array['budget', 'quick', 'vegetarian'], array['frying pan'],
   array['Slice the mushrooms and garlic.', 'Melt the butter in a frying pan over medium-high heat and fry the mushrooms for 5-6 minutes until golden and their liquid has evaporated.', 'Add the garlic for the final minute and season with salt and pepper.', 'Toast the bread in a toaster (or wipe out the pan and toast it for 1-2 minutes per side), then pile the mushrooms on top. Scatter over parsley if using.'],
   null),
  ('greek-yogurt-berry-parfait', 'Greek Yogurt Berry Parfait', 'Creamy yogurt, juicy berries and crunchy granola layered in a glass. Breakfast in five minutes, no cooking.', '🍓', 5, 0, 5, 1,
   1.30, 'Easy', array['breakfast', 'snack'], array['fresh', 'no-cook', 'quick', 'vegetarian'], array['glass or jar', 'spoon'],
   array['Spoon half of the yogurt into a glass or jar and top with half of the berries.', 'Sprinkle over half of the granola, then repeat the layers with the remaining yogurt, berries and granola.', 'Drizzle with honey if you like and eat straight away so the granola stays crunchy.'],
   null),
  ('microwave-scrambled-eggs', 'Microwave Scrambled Eggs', 'Soft, fluffy scrambled eggs in a mug in about two minutes, with no pan to wash up.', '🥚', 2, 2, 4, 1,
   0.60, 'Easy', array['breakfast'], array['budget', 'high-protein', 'quick', 'vegetarian'], array['large microwave-safe mug or bowl', 'fork'],
   array['Rub the inside of a large microwave-safe mug with butter, or leave it plain if you have none.', 'Crack in the eggs, add the milk and a pinch of salt and pepper, and beat well with a fork.', 'Microwave on high for 45 seconds, then stir, bringing the cooked edges into the middle.', 'Continue to microwave in 20-30 second bursts, stirring between each, until the eggs are fully set with no runny liquid left, about 1½-2 minutes in total.', 'Stir in the cheese if using, leave to stand for 30 seconds and eat straight away.'],
   null),
  ('breakfast-burrito', 'Breakfast Burrito', 'Scrambled eggs, black beans and melty cheese rolled in a warm tortilla. Easy to wrap in foil and eat on the go.', '🌯', 5, 10, 15, 1,
   1.40, 'Easy', array['breakfast', 'lunch'], array['high-protein', 'quick', 'vegetarian'], array['frying pan', 'bowl', 'fork'],
   array['Beat the eggs with a pinch of salt in a bowl.', 'Heat the oil in a frying pan over medium heat. Cook the diced pepper, if using, for 3 minutes, then add the beans and stir for 2 minutes until hot. Tip onto a plate.', 'Pour the eggs into the same pan and stir gently for 2-3 minutes until fully set. Take the pan off the heat.', 'Warm the tortilla in a dry frying pan for 20-30 seconds per side so it is soft and easy to fold.', 'Pile the eggs, beans and cheese down the middle, add salsa or hot sauce if you like, fold in the sides and roll up tightly.'],
   null),
  ('spinach-feta-egg-muffins', 'Spinach & Feta Egg Muffins', 'Bake a batch of fluffy egg muffins on Sunday and grab two for breakfast all week.', '🧁', 10, 20, 30, 3,
   1.00, 'Easy', array['breakfast', 'snack'], array['air-fryer', 'budget', 'high-protein', 'meal-prep', 'vegetarian'], array['6-hole muffin tin', 'mixing bowl', 'whisk or fork'],
   array['Heat the oven to 180°C (160°C fan) and grease a 6-hole muffin tin well with the oil.', 'Divide the chopped spinach, feta and pepper, if using, between the holes.', 'Beat the eggs with the milk, if using, and a little salt (feta is already salty) and pepper.', 'Pour the egg over the filling, filling each hole about three-quarters full.', 'Bake for 18-20 minutes until puffed, golden and completely set in the centre with no wobble.', 'Leave to cool in the tin for 5 minutes, then run a knife around the edges to release.'],
   'Cool, then refrigerate in a sealed container within 2 hours. Eat within 2 days, cold or reheated until piping hot.'),
  ('berry-banana-smoothie', 'Berry Banana Smoothie', 'Thick, fruity and naturally sweet. Frozen berries make it ice-cold with no ice needed.', '🫐', 5, 0, 5, 1,
   1.20, 'Easy', array['breakfast', 'snack'], array['budget', 'fresh', 'quick', 'vegetarian'], array['glass'],
   array['Peel the banana and break it into the blender.', 'Add the berries, yogurt and milk.', 'Blend for 30-60 seconds until completely smooth, adding a splash more milk if it is too thick.', 'Taste, sweeten with honey if needed, and pour into a glass.'],
   null),
  ('peanut-butter-oat-smoothie', 'Peanut Butter Oat Smoothie', 'A creamy banana, oat and peanut butter smoothie that tastes like dessert and keeps you full until lunch.', '🥜', 5, 0, 5, 1,
   0.80, 'Easy', array['breakfast', 'snack'], array['budget', 'quick', 'vegetarian'], array['glass'],
   array['Put the oats in the blender and blend for 10-15 seconds until fine, so the smoothie is not gritty.', 'Add the banana, peanut butter, milk and cinnamon, if using.', 'Blend for 45-60 seconds until smooth and creamy.', 'Taste, add honey if you like it sweeter, and drink straight away as the oats thicken it on standing.'],
   null),
  ('apple-cinnamon-porridge', 'Apple Cinnamon Porridge', 'Creamy oats with soft grated apple and warm cinnamon, like apple pie in a bowl.', '🍎', 3, 7, 10, 1,
   0.70, 'Easy', array['breakfast'], array['budget', 'comfort', 'quick', 'vegetarian'], array['saucepan', 'grater', 'wooden spoon'],
   array['Coarsely grate half of the apple, skin and all, and thinly slice the rest for the top.', 'Put the oats, milk, cinnamon and grated apple in a saucepan over medium heat.', 'Bring to a gentle simmer and cook for 4-5 minutes, stirring often, until thick and creamy. Add a splash more milk if it gets too stiff.', 'Spoon into a bowl and top with the sliced apple, a drizzle of honey and the walnuts, if using.'],
   null),
  ('chia-seed-pudding', 'Chia Seed Pudding', 'Stir it together in two minutes, leave it in the fridge, and wake up to a creamy, spoonable breakfast.', '🥄', 5, 0, 5, 2,
   0.80, 'Easy', array['breakfast', 'snack'], array['budget', 'meal-prep', 'no-cook', 'quick', 'vegetarian'], array['2 jars or containers with lids', 'whisk or fork'],
   array['Whisk the chia seeds, milk, maple syrup and vanilla, if using, together in a bowl or jug.', 'Leave for 5 minutes, then whisk again to break up any clumps of seeds.', 'Divide between two jars, cover and chill in the fridge for at least 2 hours, or overnight, until thick and set.', 'Stir, loosen with a splash of milk if needed, and top with berries just before eating.'],
   'Keep covered in the fridge and eat within 2 days. Add fruit toppings just before eating.'),
  ('cinnamon-french-toast', 'Cinnamon French Toast', 'Golden, custardy slices with a hint of cinnamon. A great way to use up bread that is going stale.', '🍞', 3, 7, 10, 1,
   0.70, 'Easy', array['breakfast'], array['budget', 'comfort', 'quick', 'vegetarian'], array['frying pan', 'shallow dish', 'fork', 'spatula'],
   array['Beat the egg, milk, cinnamon and sugar, if using, together in a shallow dish.', 'Melt the butter in a frying pan over medium heat until it starts to foam.', 'Dip each slice of bread into the egg mixture for about 10 seconds per side so it soaks up the custard without falling apart.', 'Cook the slices for 2-3 minutes per side until deep golden and the egg in the middle is cooked and set.', 'Serve hot with maple syrup and berries, if using.'],
   null),
  ('smoked-salmon-cream-cheese-bagel', 'Smoked Salmon & Cream Cheese Bagel', 'A café classic at home: toasted bagel, cool cream cheese and silky smoked salmon with a squeeze of lemon.', '🥯', 5, 3, 8, 1,
   2.40, 'Easy', array['breakfast', 'lunch'], array['high-protein', 'quick'], array['bread knife', 'butter knife'],
   array['Carefully slice the bagel in half horizontally.', 'Toast the halves in the toaster until golden and crisp at the edges.', 'Spread the cream cheese over both warm halves.', 'Top with the smoked salmon and cucumber, if using, then finish with a squeeze of lemon and plenty of black pepper.'],
   null),
  ('tomato-basil-bruschetta', 'Tomato Basil Bruschetta', 'Crunchy garlic toast piled with juicy tomatoes and fresh basil. A perfect snack for sharing.', '🍅', 10, 4, 14, 2,
   0.90, 'Easy', array['lunch', 'snack'], array['budget', 'fresh', 'quick', 'vegan', 'vegetarian'], array['chopping board', 'knife', 'bowl'],
   array['Dice the tomatoes, discarding the watery seeds, and put them in a bowl.', 'Tear in most of the basil, add 1 tbsp olive oil, the balsamic, if using, and season with salt and pepper. Leave for 5 minutes for the flavours to mingle.', 'Toast the bread until golden and crisp.', 'Rub the cut side of the garlic over the hot toast, then drizzle with the remaining olive oil.', 'Spoon the tomatoes on top just before serving and finish with the remaining basil.'],
   null),
  ('air-fryer-crispy-chickpeas', 'Air-Fryer Crispy Chickpeas', 'Crunchy, smoky chickpeas made from one can. A cheap, moreish snack to munch while you study.', '🫘', 5, 15, 20, 2,
   0.60, 'Easy', array['snack'], array['air-fryer', 'budget', 'quick', 'vegan', 'vegetarian'], array['sieve', 'kitchen paper', 'bowl'],
   array['Drain and rinse the chickpeas, then pat them very dry with kitchen paper, removing any loose skins.', 'Toss the chickpeas in a bowl with the oil, paprika, a good pinch of salt and the cumin and garlic powder, if using.', 'Spread in a single layer in the air fryer basket and cook at 200°C for 12-15 minutes, shaking every 5 minutes, until golden and crunchy.', 'Leave to cool for a few minutes so they crisp up further, then taste and add more salt if needed.'],
   'Best eaten the same day. They soften in a sealed container but can be re-crisped in the air fryer for 2-3 minutes.'),
  ('air-fryer-potato-wedges', 'Air-Fryer Potato Wedges', 'Fluffy inside, crispy outside and lightly smoky. Better than takeaway chips for a fraction of the price.', '🥔', 5, 20, 25, 2,
   0.50, 'Easy', array['snack', 'dinner'], array['air-fryer', 'budget', 'comfort', 'vegan', 'vegetarian'], array['chopping board', 'knife', 'bowl', 'kitchen paper'],
   array['Scrub the potatoes (no need to peel) and cut each one lengthways into 8 wedges.', 'Pat the wedges dry with kitchen paper, then toss in a bowl with the oil, paprika, garlic powder, if using, and a good pinch of salt.', 'Arrange in a single layer in the air fryer basket, cooking in batches if needed.', 'Cook at 200°C for 18-22 minutes, shaking halfway, until golden and crisp outside and soft when pierced with a knife.', 'Sprinkle with a little more salt and serve hot with ketchup, if using.'],
   null),
  ('microwave-chocolate-mug-cake', 'Microwave Chocolate Mug Cake', 'A warm, gooey chocolate cake for one, ready in under five minutes. No eggs and no oven needed.', '🍫', 3, 2, 5, 1,
   0.40, 'Easy', array['snack'], array['budget', 'comfort', 'quick', 'vegetarian'], array['large microwave-safe mug (at least 350 ml)', 'fork', 'skewer or knife'],
   array['Mix the flour, sugar, cocoa, baking powder and a pinch of salt in a large mug with a fork.', 'Add the milk, oil and vanilla, if using, and stir until smooth with no dry flour left at the bottom. Stir in the chocolate, if using.', 'Microwave on high for 70-90 seconds until risen and the top looks dry and springs back when touched.', 'Check it is cooked through: a skewer pushed into the centre should come out without wet batter. If not, microwave in 10-second bursts. Do not eat the raw batter, as raw flour is not safe.', 'Leave to cool for 1-2 minutes, as the mug and melted chocolate will be very hot, then eat from the mug.'],
   null),
  ('loaded-nachos', 'Loaded Nachos', 'A tray of crunchy tortilla chips smothered in melted cheese, beans and all your favourite toppings.', '🧀', 10, 8, 18, 2,
   1.50, 'Easy', array['snack', 'dinner'], array['air-fryer', 'comfort', 'quick', 'vegetarian'], array['baking tray or ovenproof dish', 'sieve'],
   array['Heat the oven to 200°C (180°C fan).', 'Spread half of the tortilla chips over a baking tray or ovenproof dish, then scatter over half of the beans and half of the cheese.', 'Repeat with the remaining chips, beans and cheese so every layer gets some topping.', 'Bake for 6-8 minutes until the cheese has melted and is bubbling, keeping an eye on the edges so the chips do not burn.', 'Top with spoonfuls of salsa and sour cream, the avocado, spring onion and chilli, if using, and eat straight away.'],
   null),
  ('hummus-veggie-snack-box', 'Hummus & Veggie Snack Box', 'Crunchy veg sticks with creamy hummus, packed into boxes for easy snacking between lectures.', '🥕', 10, 0, 10, 2,
   1.20, 'Easy', array['snack', 'lunch'], array['budget', 'fresh', 'meal-prep', 'no-cook', 'quick', 'vegan', 'vegetarian'], array['chopping board', 'knife', '2 lunch boxes with small pots'],
   array['Peel the carrots and cut them into sticks about the size of your finger.', 'Cut the cucumber and pepper, if using, into similar sticks, scooping out the watery cucumber seeds so the box stays crisp.', 'Spoon the hummus into two small pots, sprinkle with paprika if you like, and close the lids.', 'Pack the veg sticks, pitta triangles and olives, if using, around the hummus pots in two lunch boxes.'],
   'Keep the boxes sealed in the fridge and eat within 2 days, checking the hummus use-by date.'),
  ('caprese-salad', 'Caprese Salad', 'Ripe tomatoes, soft mozzarella and fragrant basil with a drizzle of good olive oil. Simple Italian summer on a plate.', '🌿', 10, 0, 10, 2,
   1.30, 'Easy', array['lunch', 'snack'], array['fresh', 'no-cook', 'quick', 'vegetarian'], array['chopping board', 'sharp knife', 'serving plate'],
   array['Take the mozzarella out of the fridge 10 minutes before serving for the best flavour, then drain and pat it dry.', 'Slice the tomatoes and mozzarella into rounds about 1 cm thick.', 'Arrange the slices on a plate, alternating and overlapping them, and tuck the basil leaves in between.', 'Drizzle with the olive oil and balsamic, if using, season with salt and pepper and serve with bread to mop up the juices.'],
   null),
  ('egg-cheese-breakfast-bagel', 'Egg & Cheese Breakfast Bagel', 'A toasted bagel stacked with a fried egg and melting cheese. Your favourite café breakfast for a fraction of the price.', '🍳', 2, 6, 8, 1,
   1.00, 'Easy', array['breakfast'], array['budget', 'high-protein', 'quick', 'vegetarian'], array['frying pan with a lid', 'spatula', 'bread knife'],
   array['Slice the bagel in half and toast it in the toaster, or cut-side down in a dry frying pan for 1-2 minutes, then spread with butter if you like.', 'Heat the oil in the frying pan over medium heat and crack in the egg. Break the yolk with a spatula so it cooks evenly and fits the bagel.', 'Cook for 2 minutes, then flip, season and lay the cheese on top. Add a splash of water, cover with the lid and cook for 1 minute until the egg is fully set and the cheese has melted.', 'Put the spinach, if using, on the bottom half of the bagel, add the egg and cheese, a dash of hot sauce if you like, and close.'],
   null),
  ('savoury-oats-fried-egg', 'Savoury Oats with Fried Egg', 'Porridge goes savoury: creamy stock-cooked oats topped with a crispy fried egg, soy and spring onion.', '🥣', 3, 8, 11, 1,
   0.60, 'Easy', array['breakfast', 'lunch'], array['budget', 'comfort', 'quick', 'vegetarian'], array['saucepan', 'frying pan', 'spatula'],
   array['Put the oats in a saucepan with 250 ml water and crumble in the stock cube.', 'Bring to a simmer over medium heat and cook for 4-5 minutes, stirring often, until thick and creamy. Stir in the cheese, if using, and season with pepper.', 'Meanwhile, heat the oil in a frying pan over medium-high heat and crack in the egg.', 'Fry for 3-4 minutes until the white is completely set with crispy edges and the yolk is cooked to your liking.', 'Spoon the oats into a bowl, top with the egg, and finish with soy sauce, spring onion and chilli flakes, if using.'],
   null),
  ('chilli-garlic-edamame', 'Chilli Garlic Edamame', 'Bright green edamame tossed in sizzling garlic, chilli and soy. Pop them from the pods and try not to finish the bowl.', '🫛', 3, 8, 11, 2,
   0.80, 'Easy', array['snack'], array['budget', 'quick', 'spicy', 'vegan', 'vegetarian'], array['saucepan', 'frying pan', 'colander'],
   array['Bring a saucepan of water to the boil, add the frozen edamame and cook for 4-5 minutes until tender. Drain well.', 'Heat the vegetable oil in a frying pan over medium-low heat. Add the garlic and chilli flakes and cook for 1 minute, stirring, until fragrant but not browned.', 'Add the drained edamame and soy sauce and toss for 1 minute until glossy and coated.', 'Drizzle with sesame oil, if using, and serve warm. Squeeze the beans out of the pods with your teeth and discard the pods.'],
   null),
  ('pitta-bread-pizzas', 'Pitta Bread Pizzas', 'Crispy pitta bases with tomato, bubbling mozzarella and your pick of toppings. Pizza night in 15 minutes.', '🍕', 5, 10, 15, 1,
   1.20, 'Easy', array['lunch', 'dinner', 'snack'], array['air-fryer', 'budget', 'comfort', 'quick', 'vegetarian'], array['baking tray', 'spoon'],
   array['Heat the oven to 200°C (180°C fan) and put the pittas on a baking tray.', 'Spread 2 tbsp passata over each pitta, leaving a thin border, and sprinkle with oregano if using.', 'Scatter over the mozzarella and any toppings you like, then drizzle with a little olive oil.', 'Bake for 8-10 minutes until the cheese is melted and bubbling and the edges are crisp.', 'Leave for 1 minute, then cut into quarters and serve.'],
   null),
  ('mango-lassi-smoothie', 'Mango Lassi Smoothie', 'Sweet mango blended with tangy yogurt into a thick, silky Indian-style lassi.', '🥭', 5, 0, 5, 1,
   1.40, 'Easy', array['breakfast', 'snack'], array['fresh', 'quick', 'vegetarian'], array['glass', 'knife'],
   array['If using fresh mango, peel it and cut the flesh away from the stone into chunks.', 'Put the mango, yogurt, milk and honey, if using, in the blender.', 'Blend for 30-60 seconds until completely smooth, adding a splash more milk if it is too thick.', 'Pour into a glass and dust with a pinch of cinnamon if you like.'],
   null),
  ('smashed-avocado-chickpea-sandwich', 'Smashed Avocado & Chickpea Sandwich', 'Creamy avocado and chickpeas smashed with lemon into a chunky, zesty sandwich filling. No cooking needed.', '🥑', 10, 0, 10, 1,
   1.50, 'Easy', array['lunch'], array['fresh', 'no-cook', 'quick', 'vegan', 'vegetarian'], array['bowl', 'fork', 'sieve'],
   array['Rinse and drain the chickpeas, then mash them roughly with a fork in a bowl, leaving some whole for texture.', 'Scoop in the avocado and mash it into the chickpeas.', 'Stir in the lemon juice, spring onion and chilli flakes, if using, and season well with salt and pepper.', 'Spread thickly onto one slice of bread, top with rocket if you like, close the sandwich and cut in half.'],
   null),
  ('cheesy-beans-on-toast', 'Cheesy Beans on Toast', 'The ultimate student comfort food: hot baked beans and melting cheese piled onto buttery toast.', '🫕', 2, 5, 7, 2,
   0.70, 'Easy', array['breakfast', 'lunch'], array['budget', 'comfort', 'quick', 'vegetarian'], array['saucepan', 'wooden spoon'],
   array['Tip the beans into a saucepan and heat over medium heat for 3-4 minutes, stirring now and then, until bubbling and piping hot.', 'Meanwhile, toast the bread in the toaster until golden and spread with butter if you like.', 'Take the beans off the heat and stir in half of the cheese until it melts.', 'Spoon the beans over the hot toast, scatter over the remaining cheese and finish with black pepper and hot sauce, if using.'],
   null),
  ('blueberry-baked-oats', 'Blueberry Baked Oats', 'A soft, cake-like tray of baked oats bursting with blueberries. Bake once and breakfast is sorted for days.', '🫐', 10, 35, 45, 4,
   0.90, 'Easy', array['breakfast', 'snack'], array['budget', 'meal-prep', 'vegetarian'], array['ovenproof dish (about 20 cm)', 'mixing bowl', 'fork'],
   array['Heat the oven to 180°C (160°C fan) and grease an ovenproof dish of about 20 cm with butter or a little oil.', 'Mash the bananas in a mixing bowl with a fork until smooth, then beat in the eggs, milk and maple syrup, if using.', 'Stir in the oats, baking powder, cinnamon, if using, and a pinch of salt.', 'Fold in two-thirds of the blueberries, pour into the dish and scatter the rest on top.', 'Bake for 30-35 minutes until golden and set, and a knife pushed into the centre comes out without any runny egg.', 'Leave to cool for 10 minutes before cutting into 4 squares.'],
   'Cool, then refrigerate in a sealed container within 2 hours. Eat within 2 days, cold or reheated until piping hot.'),
  ('tuna-cucumber-rice-cakes', 'Tuna & Cucumber Rice Cakes', 'Crunchy rice cakes topped with creamy lemony tuna and cool cucumber. A no-cook snack ready in five minutes.', '🐟', 5, 0, 5, 1,
   1.50, 'Easy', array['snack', 'lunch'], array['fresh', 'high-protein', 'no-cook', 'quick'], array['bowl', 'fork', 'knife'],
   array['Drain the tuna well and flake it into a bowl with a fork.', 'Mix in the mayonnaise, a squeeze of lemon and the spring onion, if using, and season with black pepper.', 'Lay the cucumber slices over the rice cakes and spoon the tuna on top.', 'Eat straight away, before the rice cakes soften.'],
   null),
  ('chicken-shawarma-bowls', 'Chicken Shawarma Bowls', 'Warmly spiced, golden chicken over fluffy rice with crunchy salad and a garlicky lemon yogurt sauce.', '🥙', 15, 20, 35, 2,
   2.40, 'Easy', array['lunch', 'dinner'], array['high-protein'], array['saucepan with lid', 'frying pan', 'chopping board', 'bowl'],
   array['Rinse the rice, then cook it in a saucepan with 300 ml water and a pinch of salt: bring to the boil, cover and simmer on low for 12 minutes, then rest off the heat for 5 minutes.', 'Cut the chicken into bite-sized strips. Toss with the cumin, paprika, turmeric if using, half the lemon juice, 1 crushed garlic clove, the oil and a good pinch of salt. Wash your hands and the board after handling raw chicken.', 'Heat a frying pan over medium-high heat and cook the chicken for 8-10 minutes, turning now and then, until charred at the edges and cooked through with no pink inside (75°C).', 'Meanwhile, stir the other crushed garlic clove, the rest of the lemon juice and a pinch of salt into the yogurt.', 'Divide the rice between two bowls, top with the chicken, cucumber and tomato, and spoon over the yogurt sauce.'],
   null),
  ('mediterranean-couscous-salad', 'Mediterranean Couscous Salad', 'Fluffy lemony couscous tossed with cucumber, tomato and salty feta. Made with just a kettle.', '🥗', 10, 5, 15, 2,
   1.60, 'Easy', array['lunch'], array['fresh', 'meal-prep', 'quick', 'vegetarian'], array['heatproof bowl', 'plate or lid', 'fork', 'chopping board'],
   array['Boil the kettle. Put the couscous in a heatproof bowl with a pinch of salt (or crumble in the stock cube) and pour over 200 ml of the boiling water.', 'Cover with a plate and leave for 5 minutes, then fluff up with a fork and let it cool for a few minutes.', 'Meanwhile, dice the cucumber and tomatoes.', 'Whisk the olive oil with the juice of the lemon and some salt and pepper, then stir it through the couscous.', 'Fold in the cucumber, tomatoes, olives and herbs if using, and crumble the feta over the top.'],
   'Keep in a sealed container in the fridge and eat within 2 days.'),
  ('quinoa-black-bean-salad', 'Quinoa Black Bean Salad', 'Zesty lime and cumin quinoa with black beans, sweetcorn and crunchy pepper. Great packed for campus.', '🫘', 10, 15, 25, 3,
   1.30, 'Easy', array['lunch'], array['fresh', 'meal-prep', 'vegan', 'vegetarian'], array['saucepan', 'sieve', 'large bowl', 'chopping board'],
   array['Rinse the quinoa well in a sieve, then put it in a saucepan with 300 ml water and a pinch of salt.', 'Bring to the boil, then cover and simmer on low for 12-15 minutes until the water is absorbed and the grains have little tails. Spread out to cool.', 'Meanwhile, dice the pepper and whisk the lime juice, olive oil, cumin and a pinch of salt in a large bowl.', 'Add the cooled quinoa, beans, sweetcorn, pepper and red onion if using, and toss well.', 'Taste for salt, then scatter with coriander and avocado if you like.'],
   'Cool the quinoa quickly, keep the salad in a sealed container in the fridge and eat within 2 days. Add avocado just before eating.'),
  ('classic-tuna-melt', 'Classic Tuna Melt', 'Creamy tuna and gooey melted cheese in a crisp golden sandwich. The ultimate cupboard lunch.', '🥪', 5, 8, 13, 1,
   1.50, 'Easy', array['lunch'], array['comfort', 'high-protein', 'quick'], array['frying pan', 'spatula', 'bowl', 'fork'],
   array['Mix the drained tuna with the mayonnaise, spring onion if using and a pinch of black pepper.', 'Spread the tuna over one slice of bread, top with the cheese and the second slice. Thinly butter the outside of the sandwich if you like.', 'Heat a frying pan over medium-low heat and cook the sandwich for 3-4 minutes, pressing down gently with a spatula, until golden underneath.', 'Flip and cook for another 3-4 minutes until golden and the cheese has melted. Cut in half and eat while hot.'],
   null),
  ('halloumi-veg-wraps', 'Halloumi & Veg Wraps', 'Squeaky golden halloumi and charred peppers and courgette rolled up in warm tortillas.', '🌯', 10, 12, 22, 2,
   2.40, 'Easy', array['lunch', 'dinner'], array['vegetarian'], array['frying pan', 'chopping board'],
   array['Heat the oil in a frying pan over medium-high heat. Cook the pepper and courgette for 6-7 minutes, stirring now and then, until soft and charred in places. Season with pepper and tip onto a plate.', 'Pat the halloumi slices dry and add them to the same pan. Cook for 1-2 minutes per side until deep golden.', 'Warm the tortillas in the dry pan for about 20 seconds per side.', 'Spread each tortilla with hummus if using, add the veg, halloumi and rocket, squeeze over some lemon and roll up tightly.'],
   null),
  ('chicken-caesar-wraps', 'Chicken Caesar Wraps', 'Juicy chicken, crisp lettuce and a quick creamy parmesan dressing, all wrapped up to go.', '🌯', 10, 12, 22, 2,
   2.30, 'Easy', array['lunch'], array['high-protein'], array['frying pan', 'chopping board', 'small bowl'],
   array['Slice the chicken breast in half horizontally to make two thin fillets and season with salt and pepper. Wash your hands and the board after handling raw chicken.', 'Heat the oil in a frying pan over medium heat and cook the chicken for 5-6 minutes per side until golden and cooked through with no pink inside (75°C). Rest for 2 minutes, then slice.', 'Meanwhile, mix the mayonnaise with the lemon juice, most of the parmesan, plus the garlic and mustard if using, and plenty of black pepper.', 'Toss the lettuce with the dressing, pile it onto the tortillas with the chicken and the rest of the parmesan, then roll up tightly.'],
   null),
  ('air-fryer-chickpea-falafel-pittas', 'Air-Fryer Chickpea Falafel Pittas', 'Crisp, herby falafel made from a can of chickpeas, stuffed into warm pittas with salad.', '🧆', 15, 15, 30, 2,
   1.30, 'Medium', array['lunch', 'dinner'], array['air-fryer', 'vegetarian'], array['bowl', 'kitchen paper', 'spatula'],
   array['Drain the chickpeas and pat them very dry with kitchen paper, as wet chickpeas make soft falafel.', 'Put the chickpeas, onion, garlic, cumin, parsley if using and a good pinch of salt in a blender. Pulse until finely chopped but not a smooth paste, scraping down the sides.', 'Tip into a bowl and mix in the flour. Shape into 10-12 small flattened balls and brush or drizzle them with the oil.', 'Air fry at 190°C for 12-15 minutes, turning halfway, until golden and crisp on the outside.', 'Warm the pittas in the air fryer for 1 minute, split them open and fill with lettuce, tomato, the falafel and a spoonful of yogurt.'],
   null),
  ('sweet-chilli-prawn-rice-bowls', 'Sweet Chilli Prawn Rice Bowls', 'Sticky garlic prawns glazed in sweet chilli sauce over fluffy rice with cool cucumber.', '🍤', 10, 15, 25, 2,
   1.80, 'Easy', array['lunch', 'dinner'], '{}'::text[], array['saucepan with lid', 'frying pan'],
   array['Rinse the rice, then cook it in a saucepan with 300 ml water and a pinch of salt: bring to the boil, cover and simmer on low for 12 minutes, then rest off the heat for 5 minutes.', 'Pat the prawns dry with kitchen paper.', 'Heat the oil in a frying pan over medium-high heat. Add the garlic and prawns and cook for 2-3 minutes, turning once, until the prawns have turned pink all over and are opaque in the middle.', 'Stir in the sweet chilli sauce and soy sauce if using and bubble for 30 seconds until glossy.', 'Spoon the prawns over the rice and serve with cucumber, spring onion and lime wedges.'],
   null),
  ('teriyaki-tofu-rice-bowls', 'Teriyaki Tofu Rice Bowls', 'Golden, crispy-edged tofu in a sticky teriyaki glaze, served over rice with tender broccoli.', '🍚', 15, 20, 35, 2,
   1.60, 'Easy', array['lunch', 'dinner'], array['vegan', 'vegetarian'], array['saucepan with lid', 'non-stick frying pan', 'kitchen paper'],
   array['Wrap the tofu in kitchen paper or a clean tea towel and press it under something heavy for 10 minutes to squeeze out water.', 'Meanwhile, rinse the rice and cook it in a saucepan with 300 ml water and a pinch of salt: bring to the boil, cover and simmer on low for 12 minutes, then rest off the heat for 5 minutes.', 'Cut the tofu into 2 cm cubes. Heat the oil in a non-stick frying pan over medium-high heat and fry the tofu for 8-10 minutes, turning, until golden on most sides.', 'If using broccoli, add it with 3 tbsp water, cover and steam for 3 minutes until just tender.', 'Pour in the teriyaki sauce and toss for 1 minute until everything is glossy. Serve over the rice, scattered with sesame seeds and spring onion.'],
   null),
  ('warm-lentil-feta-salad', 'Warm Lentil & Feta Salad', 'Earthy lentils warmed with garlic and balsamic, tossed with wilting spinach and salty feta.', '🥗', 5, 10, 15, 2,
   1.60, 'Easy', array['lunch', 'dinner'], array['one-pan', 'quick', 'vegetarian'], array['frying pan', 'chopping board'],
   array['Thinly slice the onion and chop the garlic.', 'Heat 1 tbsp of the oil in a frying pan over medium heat and cook the onion for 5 minutes until soft. Add the garlic for the last minute.', 'Add the lentils and sun-dried tomatoes if using, and stir for 2-3 minutes until warmed through.', 'Take the pan off the heat and stir in the spinach so it just wilts, then add the balsamic vinegar, the remaining oil and season with salt and pepper.', 'Crumble over the feta and scatter with parsley if you like. Eat warm.'],
   null),
  ('egg-mayo-sandwiches', 'Egg Mayo Sandwiches', 'Soft bread packed with creamy, peppery egg mayo. A cheap lunchbox classic.', '🥪', 10, 10, 20, 2,
   0.70, 'Easy', array['lunch'], array['budget', 'quick', 'vegetarian'], array['saucepan', 'bowl', 'fork'],
   array['Bring a saucepan of water to the boil, gently lower in the eggs and simmer for 10 minutes so the yolks are fully set.', 'Drain and cool the eggs in cold water for a few minutes, then peel them.', 'Mash the eggs with a fork and mix in the mayonnaise, mustard and spring onion if using, plus salt and pepper.', 'Spread the egg mayo over two slices of bread, add lettuce if you like, top with the remaining bread and cut in half.'],
   'Keep any leftover egg mayo covered in the fridge and eat within 2 days.'),
  ('pesto-pasta-salad', 'Pesto Pasta Salad', 'Bright basil pesto pasta with juicy tomatoes and mozzarella. Make once, lunch sorted for days.', '🍝', 5, 12, 17, 3,
   1.30, 'Easy', array['lunch'], array['fresh', 'meal-prep', 'quick', 'vegetarian'], array['large pot', 'colander', 'large bowl'],
   array['Bring a large pot of salted water to the boil and cook the pasta according to the packet.', 'Drain, rinse briefly under cold water to cool, then drain well and toss with the olive oil so it doesn''t stick.', 'Chop the tomatoes.', 'Stir the pesto through the pasta, then fold in the tomatoes, mozzarella and rocket if using. Taste for salt.'],
   'Cool and refrigerate in sealed containers within 2 hours of cooking. Eat cold within 2 days, adding the rocket just before eating.'),
  ('peanut-noodle-salad', 'Peanut Noodle Salad', 'Slurpy cold noodles in a creamy peanut, soy and lime dressing with crunchy carrot and cucumber.', '🥜', 10, 5, 15, 2,
   1.20, 'Easy', array['lunch'], array['budget', 'fresh', 'quick', 'vegan', 'vegetarian'], array['saucepan', 'colander', 'large bowl', 'grater'],
   array['Cook the noodles in a saucepan of boiling water according to the packet, then drain and rinse under cold water until cool.', 'In a large bowl, whisk the peanut butter, soy sauce, lime juice, maple syrup and sesame oil if using with 2-3 tbsp warm water until smooth and pourable.', 'Add the noodles, carrot and cucumber and toss until everything is coated.', 'Top with chilli, chopped peanuts and coriander if you like.'],
   null),
  ('burrito-bowls', 'Burrito Bowls', 'All the best bits of a burrito without the wrap: smoky beans, rice, sweetcorn and salsa.', '🌯', 10, 20, 30, 2,
   1.40, 'Easy', array['lunch', 'dinner'], array['meal-prep', 'vegetarian'], array['saucepan with lid', 'frying pan'],
   array['Rinse the rice, then cook it in a saucepan with 300 ml water and a pinch of salt: bring to the boil, cover and simmer on low for 12 minutes, then rest off the heat for 5 minutes.', 'Meanwhile, heat the oil in a frying pan over medium heat, add the cumin and paprika and stir for 30 seconds.', 'Add the beans and a splash of water and cook for 4-5 minutes, lightly crushing a few beans, until hot. Season with salt.', 'Stir the sweetcorn into the beans for the last minute to warm through.', 'Divide the rice between bowls and top with the beans and corn, salsa, and cheese, avocado, sour cream and lime if using.'],
   'Cool quickly and refrigerate within 2 hours. Eat the rice within 24 hours and the beans within 2 days, reheating until piping hot. Add the toppings fresh.'),
  ('tomato-mozzarella-panini', 'Tomato & Mozzarella Panini', 'Crisp, golden bread with melting mozzarella and juicy tomato. No panini press needed.', '🥪', 5, 8, 13, 1,
   1.40, 'Easy', array['lunch'], array['comfort', 'quick', 'vegetarian'], array['frying pan', 'a second heavy pan or plate to press', 'kitchen paper'],
   array['Pat the mozzarella and tomato slices dry with kitchen paper so the panini stays crisp.', 'Spread one slice of bread with pesto if using, layer on the tomato, mozzarella and basil, season, and top with the second slice. Brush the outside with the oil.', 'Heat a frying pan over medium-low heat. Add the sandwich and press it down with a second heavy pan or a plate.', 'Cook for 3-4 minutes per side until golden and crisp and the mozzarella has melted. Cut in half and serve.'],
   null),
  ('10-minute-tomato-soup', '10-Minute Tomato Soup', 'Silky, comforting tomato soup made from a carton of passata. Perfect with buttered toast.', '🍅', 2, 8, 10, 2,
   0.70, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'quick', 'vegetarian'], array['saucepan', 'wooden spoon'],
   array['Heat the oil in a saucepan over medium-low heat and gently cook the garlic for 1 minute without letting it brown.', 'Pour in the passata and 200 ml water, crumble in the stock cube and add the oregano and sugar if using.', 'Bring to the boil, then simmer for 5 minutes, stirring now and then.', 'Season with salt and pepper and swirl in the cream if you like. Serve hot.'],
   null),
  ('minestrone-soup', 'Minestrone Soup', 'A big, cosy pot of Italian vegetable, bean and pasta soup that tastes even better the next day.', '🥣', 10, 30, 40, 4,
   1.00, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'meal-prep', 'vegetarian'], array['large pot', 'chopping board', 'wooden spoon'],
   array['Finely dice the onion, carrots and celery, and chop the garlic.', 'Heat the oil in a large pot over medium heat and cook the onion, carrot and celery for 8 minutes until softened. Add the garlic and dried herbs for the last minute.', 'Add the canned tomatoes, 1 litre of water and the crumbled stock cube. Bring to the boil, then simmer for 10 minutes.', 'Add the beans, pasta and courgette if using, and simmer for another 10 minutes until the pasta is tender, adding a splash more water if it gets too thick.', 'Stir in the spinach until wilted, season with salt and pepper, and serve with grated parmesan.'],
   'Cool within 2 hours, then refrigerate and eat within 2 days. The pasta soaks up liquid, so add a splash of water and reheat until piping hot.'),
  ('leek-potato-soup', 'Leek & Potato Soup', 'Thick, velvety and buttery. A cheap, cosy soup made from just a few humble vegetables.', '🥔', 10, 25, 35, 3,
   0.80, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'meal-prep', 'vegetarian'], array['large pot', 'chopping board', 'potato masher'],
   array['Wash the sliced leeks well in a bowl of water to remove any grit, then drain. Chop the onion.', 'Melt the butter in a large pot over medium-low heat and cook the leeks and onion for 8 minutes, stirring, until soft but not browned.', 'Add the potatoes, 800 ml water and the crumbled stock cube. Bring to the boil, then simmer for 15 minutes until the potatoes are very tender.', 'For a smooth soup, let it cool for a few minutes, then blend in batches, filling the blender no more than halfway. Or mash it in the pot for a chunky soup.', 'Stir in the milk if using, reheat gently and season with salt and plenty of black pepper.'],
   'Cool within 2 hours, refrigerate and eat within 2 days. Reheat until piping hot.'),
  ('greek-chicken-pittas', 'Greek Chicken Pittas', 'Lemon and oregano chicken stuffed into warm pittas with a quick homemade tzatziki.', '🥙', 15, 12, 27, 2,
   2.20, 'Easy', array['lunch', 'dinner'], array['fresh', 'high-protein'], array['frying pan', 'chopping board', 'grater', 'bowl'],
   array['Cut the chicken into thin strips and toss with the oregano, half the lemon juice, half the garlic, the oil, salt and pepper. Wash your hands and the board after handling raw chicken.', 'For the tzatziki, grate the cucumber, squeeze out the water with your hands, then mix with the yogurt, the remaining garlic and a pinch of salt.', 'Heat a frying pan over medium-high heat and cook the chicken for 6-8 minutes, turning, until golden and cooked through with no pink inside (75°C). Squeeze over the rest of the lemon.', 'Warm the pittas in the pan for 30 seconds per side, then split them open.', 'Fill with tzatziki, chicken, and tomato, red onion and feta if using.'],
   null),
  ('smoked-salmon-sushi-bowls', 'Smoked Salmon Sushi Bowls', 'All the flavours of sushi with zero rolling: seasoned rice, smoked salmon, avocado and cucumber.', '🍣', 10, 20, 30, 2,
   2.40, 'Easy', array['lunch', 'dinner'], array['fresh'], array['saucepan with lid', 'sieve', 'small bowl'],
   array['Rinse the rice in a sieve until the water runs clear.', 'Put it in a saucepan with 250 ml water, bring to the boil, then cover and simmer on the lowest heat for 12 minutes. Take off the heat and leave covered for 10 minutes.', 'Stir the vinegar, sugar and a pinch of salt together until dissolved, then gently fold through the warm rice. Spread it out for a few minutes to cool slightly.', 'Divide the rice between bowls and arrange the smoked salmon, cucumber and avocado on top.', 'Sprinkle with sesame seeds and spring onion and drizzle with soy sauce to serve.'],
   null),
  ('chopped-chickpea-salad', 'Chopped Chickpea Salad', 'Crunchy, zesty and ready in 10 minutes with no cooking at all. Just chop, toss and eat.', '🥗', 10, 0, 10, 2,
   1.00, 'Easy', array['lunch'], array['budget', 'fresh', 'no-cook', 'quick', 'vegetarian'], array['large bowl', 'chopping board', 'knife'],
   array['Chop the cucumber, tomatoes and pepper into small, even pieces, about the size of a chickpea.', 'In a large bowl, whisk the olive oil with the lemon juice, oregano, salt and pepper.', 'Add the chickpeas, chopped vegetables and red onion if using, and toss well.', 'Top with crumbled feta and parsley if you like, and eat straight away.'],
   null),
  ('ham-cheese-toastie', 'Ham & Cheese Toastie', 'Buttery, crunchy bread with salty ham and stretchy melted cheese. Pure comfort in 10 minutes.', '🧀', 3, 7, 10, 1,
   1.10, 'Easy', array['lunch', 'snack'], array['air-fryer', 'budget', 'comfort', 'quick'], array['frying pan', 'spatula'],
   array['Butter one side of each slice of bread.', 'Place one slice butter-side down, spread with mustard if using, then add half the cheese, the ham and the rest of the cheese. Top with the second slice, butter-side up.', 'Heat a frying pan over medium-low heat and cook the toastie for 3-4 minutes, pressing gently with a spatula, until golden underneath.', 'Flip and cook for 3 minutes more until golden and the cheese has melted. Leave for 1 minute before cutting.'],
   null),
  ('peanut-butter-ramen', 'Peanut Butter Ramen', 'Creamy, savoury peanut broth with slurpy noodles. A cheap late-lecture lunch in 10 minutes.', '🍜', 2, 8, 10, 1,
   0.80, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'quick', 'vegan', 'vegetarian'], array['saucepan', 'small bowl'],
   array['Bring 400 ml water to the boil in a saucepan and crumble in the stock cube.', 'Add the noodles and simmer for 3-4 minutes, or according to the packet, until tender. Stir in the spinach for the last 30 seconds if using.', 'Meanwhile, mix the peanut butter, soy sauce, garlic and hot sauce if using in a serving bowl to a paste.', 'Ladle a little of the hot broth into the bowl and whisk until smooth, then add the noodles and the rest of the broth and stir.', 'Top with spring onion and sesame seeds if you like.'],
   null),
  ('prawn-noodle-soup', 'Prawn Noodle Soup', 'A fragrant ginger and garlic broth with juicy prawns, noodles and tender greens.', '🍜', 10, 12, 22, 2,
   2.00, 'Easy', array['lunch', 'dinner'], array['fresh'], array['large saucepan', 'grater'],
   array['Bring 800 ml water to the boil in a large saucepan. Crumble in the stock cube and add the ginger, garlic and soy sauce. Simmer for 5 minutes.', 'Add the noodles and cook according to the packet, usually 3-4 minutes.', 'Add the prawns and pak choi if using and simmer for 2-3 minutes until the prawns have turned pink all over and are opaque in the middle.', 'Taste the broth and add a splash more soy sauce if needed.', 'Ladle into bowls and top with spring onion, chilli and a squeeze of lime.'],
   null),
  ('air-fryer-salmon-bowls', 'Air-Fryer Salmon Bowls', 'Sticky soy-glazed salmon over fluffy rice with crunchy cucumber. Feels like a takeaway, made in your kitchen.', '🍣', 10, 15, 25, 2,
   3.40, 'Easy', array['lunch', 'dinner'], array['air-fryer', 'fresh', 'high-protein'], array['saucepan with a lid', 'small bowl'],
   array['Rinse the rice and cook it in a saucepan according to the packet instructions.', 'Mix the soy sauce with the honey (if using) and the oil. Set half aside in a clean bowl for serving, then brush the rest over the salmon fillets.', 'Preheat the air fryer to 200°C. Cook the salmon in the basket for 8-10 minutes, until it is opaque all the way through and flakes easily with a fork.', 'While the salmon cooks, slice the cucumber and any optional toppings.', 'Divide the rice between two bowls, flake the salmon on top and add the cucumber, avocado and spring onion. Drizzle over the reserved soy mixture and sprinkle with sesame seeds.'],
   null),
  ('garlic-butter-mushroom-pasta', 'Garlic Butter Mushroom Pasta', 'Golden mushrooms, lots of garlic and a silky butter sauce. A cosy bowl from a handful of basics.', '🍄', 5, 15, 20, 2,
   1.30, 'Easy', array['lunch', 'dinner'], array['comfort', 'quick', 'vegetarian'], array['large pot', 'large frying pan', 'colander'],
   array['Bring a large pot of salted water to the boil and cook the pasta according to the packet.', 'Meanwhile, heat the oil in a large frying pan over medium-high heat. Add the mushrooms in a single layer and cook for 6-8 minutes, stirring only now and then, until golden.', 'Turn the heat down to medium, add the butter and garlic and cook for 1-2 minutes until the garlic smells sweet but has not browned.', 'Scoop out a mugful of pasta water, then drain the pasta and add it to the frying pan with a good splash of the water.', 'Toss over low heat for 1 minute until glossy, season with salt and pepper and finish with parmesan and parsley if you have them.'],
   null),
  ('creamy-pesto-gnocchi', 'Creamy Pesto Gnocchi', 'Pillowy gnocchi in a creamy pesto sauce, ready in about 10 minutes from a few things in your fridge.', '🌿', 2, 10, 12, 2,
   1.80, 'Easy', array['lunch', 'dinner'], array['comfort', 'quick', 'vegetarian'], array['large pot', 'frying pan', 'slotted spoon'],
   array['Bring a large pot of salted water to the boil and add the gnocchi. Cook for 2-3 minutes until they float to the surface, then lift them out with a slotted spoon, saving a mugful of the water.', 'Put the cream and pesto in a frying pan over medium-low heat and stir until smooth and just bubbling.', 'Add the cherry tomatoes and spinach if using and cook for 1-2 minutes until the spinach wilts.', 'Tip in the gnocchi and toss to coat, adding a splash of the cooking water if the sauce is too thick. Season with pepper and serve topped with parmesan.'],
   null),
  ('loaded-sweet-potatoes', 'Loaded Sweet Potatoes', 'Soft, sweet baked potatoes piled high with smoky beans, sweetcorn and melted cheese.', '🍠', 10, 55, 65, 2,
   1.50, 'Easy', array['lunch', 'dinner'], array['comfort', 'vegetarian'], array['baking tray', 'fork', 'bowl'],
   array['Preheat the oven to 200°C (180°C fan). Scrub the sweet potatoes, prick them all over with a fork and rub with the oil and a pinch of salt.', 'Bake on a baking tray for 45-50 minutes until completely soft when pierced with a knife.', 'Meanwhile, mix the drained beans with the sweetcorn and paprika (if using) and a pinch of salt.', 'Split the potatoes open, spoon in the bean mixture and top with the cheese. Return to the oven for 5 minutes until the filling is hot and the cheese has melted.', 'Serve with sour cream, salsa and spring onion if you like.'],
   null),
  ('spaghetti-bolognese', 'Spaghetti Bolognese', 'A rich, slow-simmered meat sauce that tastes even better the next day. Make a big pot and eat well all week.', '🍝', 10, 40, 50, 4,
   2.00, 'Easy', array['dinner'], array['comfort', 'high-protein', 'meal-prep'], array['large saucepan or deep frying pan', 'large pot', 'colander', 'separate chopping board for raw meat'],
   array['Heat the oil in a large saucepan over medium heat and soften the onion and carrot for 6-8 minutes. Add the garlic for the last minute.', 'Turn up the heat, add the mince and break it up with a wooden spoon. Fry for 6-8 minutes until browned all over and there is no pink left. Wash your hands after handling raw mince.', 'Stir in the tomato puree and oregano if using, then the canned tomatoes and 150 ml water (crumble in the stock cube if using).', 'Bring to a bubble, then simmer gently for 25 minutes, stirring now and then, until thick and the meat is cooked through (75°C if you have a thermometer). Season with salt and pepper.', 'While the sauce simmers, cook the spaghetti in a large pot of boiling salted water according to the packet, then drain.', 'Serve the sauce over the spaghetti with parmesan if you have it.'],
   'Cool the sauce within 2 hours, then refrigerate in a sealed container and eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('chilli-con-carne', 'Chilli Con Carne', 'Smoky, warming beef and bean chilli that feeds a crowd or fills your fridge for the next couple of days.', '🌶️', 10, 40, 50, 4,
   2.00, 'Easy', array['dinner'], array['comfort', 'high-protein', 'meal-prep', 'spicy'], array['large saucepan with a lid', 'saucepan', 'separate chopping board for raw meat'],
   array['Heat the oil in a large saucepan over medium heat and cook the onion and pepper for 5 minutes until soft. Add the garlic for the last minute.', 'Add the mince and fry for 6-8 minutes, breaking it up, until browned with no pink left. Wash your hands after handling raw mince.', 'Stir in the chilli powder, cumin and tomato puree (if using) and cook for 1 minute.', 'Add the canned tomatoes, kidney beans and 150 ml water. Cover and simmer for 25 minutes, stirring occasionally, until thick and the meat is cooked through (75°C). Season with salt.', 'Meanwhile, cook the rice in a saucepan according to the packet instructions.', 'Serve the chilli over the rice with a spoonful of sour cream if you like.'],
   'Cool within 2 hours and refrigerate. Eat the chilli within 2 days (or freeze for up to 3 months) and the cooked rice within 24 hours. Reheat until piping hot.'),
  ('chicken-fajitas', 'Chicken Fajitas', 'Sizzling spiced chicken and peppers wrapped in warm tortillas. Pile on your favourite toppings.', '🌯', 10, 15, 25, 2,
   2.60, 'Easy', array['dinner'], array['high-protein'], array['large frying pan', 'separate chopping board for raw meat'],
   array['Slice the chicken into thin strips on a separate board and toss with the paprika, cumin, chilli powder (if using) and a pinch of salt. Wash your hands and the board after handling raw chicken.', 'Heat half the oil in a large frying pan over high heat and cook the pepper and onion for 5-6 minutes until softened and charred in places. Tip onto a plate.', 'Add the rest of the oil and the chicken and cook for 6-8 minutes, turning, until golden and cooked through with no pink in the middle (75°C if you have a thermometer).', 'Return the vegetables to the pan and squeeze over the lime juice if using.', 'Warm the tortillas in a dry frying pan for 20 seconds per side, then fill with the chicken mixture and your choice of toppings.'],
   null),
  ('air-fryer-paprika-chicken-thighs', 'Air-Fryer Paprika Chicken Thighs', 'Juicy smoky-paprika chicken with crispy edges and almost no washing up. Great with rice, salad or bread.', '🍗', 5, 20, 25, 2,
   2.30, 'Easy', array['lunch', 'dinner'], array['air-fryer', 'high-protein'], array['bowl', 'separate chopping board for raw meat'],
   array['In a bowl, toss the chicken thighs with the oil, paprika, salt, pepper and the garlic powder and oregano if using. Wash your hands after handling raw chicken.', 'Preheat the air fryer to 200°C. Arrange the thighs in the basket in a single layer, cooking in batches if needed.', 'Air fry for 18-22 minutes, turning halfway, until golden and cooked through with no pink in the middle (75°C if you have a thermometer).', 'Rest for 2 minutes, then squeeze over a little lemon juice if you like and serve.'],
   null),
  ('honey-garlic-chicken', 'Honey Garlic Chicken', 'Tender chicken bites in a sticky, sweet-salty glaze over rice. Better than the takeaway version.', '🍯', 10, 20, 30, 2,
   2.30, 'Easy', array['dinner'], array['high-protein'], array['large frying pan', 'saucepan', 'small bowl', 'separate chopping board for raw meat'],
   array['Cook the rice in a saucepan according to the packet instructions (add the broccoli to a pan of boiling water for the last 4 minutes if using).', 'Cut the chicken into bite-sized pieces on a separate board. Wash your hands and the board after handling raw chicken. Mix the honey, soy sauce and 2 tbsp water in a small bowl.', 'Heat the oil in a large frying pan over medium-high heat and cook the chicken for 6-8 minutes, turning, until golden and cooked through with no pink in the middle (75°C if you have a thermometer).', 'Turn the heat down, add the garlic and cook for 30 seconds, then pour in the honey mixture.', 'Simmer for 2-3 minutes, stirring, until the sauce is sticky and coats the chicken. Serve over the rice with spring onion and sesame seeds.'],
   null),
  ('beef-broccoli-stir-fry', 'Beef & Broccoli Stir-Fry', 'Tender beef and crisp broccoli tossed in a glossy garlic-soy sauce. On the table in 25 minutes.', '🥦', 10, 15, 25, 2,
   3.20, 'Medium', array['dinner'], array['high-protein', 'one-pan'], array['wok or large frying pan', 'saucepan', 'separate chopping board for raw meat'],
   array['Cook the rice in a saucepan according to the packet instructions. Mix the soy sauce, honey (if using) and 3 tbsp water in a small bowl.', 'Pat the beef strips dry. Wash your hands and the board after handling raw beef.', 'Heat half the oil in a wok over high heat and stir-fry the broccoli with 2 tbsp water for 3-4 minutes until bright green and just tender. Tip onto a plate.', 'Add the rest of the oil and stir-fry the beef in a single layer for 3-4 minutes until browned and cooked through with no pink (75°C if you have a thermometer).', 'Add the garlic and ginger for 30 seconds, then return the broccoli, pour in the sauce and toss for 1-2 minutes until glossy. Drizzle with sesame oil and serve over the rice.'],
   null),
  ('turkey-meatballs-tomato-sauce', 'Turkey Meatballs in Tomato Sauce', 'Tender herby meatballs simmered in a rich tomato sauce. Serve with pasta, rice or crusty bread.', '🧆', 15, 25, 40, 4,
   1.90, 'Medium', array['dinner'], array['comfort', 'high-protein'], array['large frying pan with a lid', 'mixing bowl', 'separate chopping board for raw meat'],
   array['In a mixing bowl, combine the turkey, breadcrumbs, egg, half the garlic, the herbs and parmesan (if using), salt and pepper. Roll into about 16 walnut-sized balls. Wash your hands well after handling raw meat.', 'Heat the oil in a large frying pan over medium heat and brown the meatballs for 5-6 minutes, turning gently, until coloured all over.', 'Add the rest of the garlic for 30 seconds, then pour in the passata and 100 ml water.', 'Cover and simmer gently for 15 minutes, turning the meatballs once, until cooked through with no pink in the middle (75°C if you have a thermometer).', 'If serving with pasta, cook it in boiling salted water while the sauce simmers. Serve the meatballs and sauce topped with torn basil.'],
   'Cool within 2 hours, refrigerate and eat within 2 days. Reheat until piping hot.'),
  ('sausage-veg-traybake', 'Sausage & Veg Traybake', 'Crispy potatoes, sticky roasted veg and golden sausages, all on one tray. Minimal effort, maximum comfort.', '🌭', 10, 45, 55, 2,
   2.00, 'Easy', array['dinner'], array['comfort', 'one-pan'], array['large baking tray'],
   array['Preheat the oven to 200°C (180°C fan).', 'Toss the potatoes with 1 tbsp oil, salt and pepper on a large baking tray and roast for 15 minutes.', 'Add the pepper, onion and zucchini (if using), drizzle with the rest of the oil and sprinkle over the herbs. Nestle the sausages in between. Wash your hands after handling raw sausages.', 'Roast for 25-30 minutes more, turning everything halfway, until the potatoes are crisp and the sausages are browned and cooked through with no pink in the middle (75°C).', 'Serve straight from the tray with mustard on the side if you like.'],
   null),
  ('lemon-garlic-prawn-pasta', 'Lemon Garlic Prawn Pasta', 'Juicy prawns, garlic and bright lemon tossed through spaghetti. Restaurant vibes in 20 minutes.', '🍤', 5, 15, 20, 2,
   2.60, 'Easy', array['dinner'], array['fresh', 'high-protein', 'quick'], array['large pot', 'large frying pan', 'colander'],
   array['Cook the pasta in a large pot of boiling salted water according to the packet. Save a mugful of pasta water before draining.', 'Meanwhile, heat the oil in a large frying pan over medium heat and cook the garlic and chilli flakes (if using) for 1 minute without browning.', 'Add the prawns and cook for 2-3 minutes, turning once, until they have turned pink all over and are cooked through. Wash your hands after handling raw prawns.', 'Add the drained pasta, the butter if using, the zest and juice of the lemon and a splash of pasta water. Toss for 1 minute until glossy.', 'Season with salt and finish with parsley.'],
   null),
  ('baked-white-fish-tomatoes-olives', 'Baked White Fish with Tomatoes & Olives', 'Flaky white fish baked on jammy tomatoes and olives. A sunny Mediterranean dinner from a single dish.', '🐟', 10, 25, 35, 2,
   3.00, 'Easy', array['dinner'], array['fresh', 'high-protein', 'one-pan'], array['oven dish'],
   array['Preheat the oven to 200°C (180°C fan).', 'Put the tomatoes, olives and garlic in an oven dish, drizzle with the oil, sprinkle with the oregano (if using) and season. Roast for 10 minutes until the tomatoes start to soften.', 'Season the fish and nestle it in among the tomatoes, spooning some of the juices over the top.', 'Bake for 12-15 minutes until the fish is opaque all the way through and flakes easily with a fork.', 'Squeeze over the lemon, scatter with parsley and serve with bread to mop up the juices.'],
   null),
  ('easy-chicken-curry', 'Easy Chicken Curry', 'A mellow, saucy curry with tender chicken that is perfect for batch cooking. Just add rice.', '🍛', 10, 35, 45, 4,
   2.00, 'Easy', array['dinner'], array['comfort', 'high-protein', 'meal-prep'], array['large saucepan with a lid', 'saucepan', 'separate chopping board for raw meat'],
   array['Cut the chicken into bite-sized pieces on a separate board. Wash your hands and the board after handling raw chicken.', 'Heat the oil in a large saucepan over medium heat and cook the onion for 6-8 minutes until soft. Add the garlic and ginger (if using) and cook for 1 minute.', 'Stir in the curry powder for 30 seconds, then add the chicken and cook for 3-4 minutes, stirring, until sealed all over.', 'Pour in the canned tomatoes and the coconut milk (or 150 ml water). Cover and simmer for 20 minutes, stirring now and then, until the chicken is cooked through with no pink in the middle (75°C). Season with salt.', 'Meanwhile, cook the rice in a saucepan according to the packet instructions.', 'Serve the curry over the rice, scattered with coriander.'],
   'Cool within 2 hours and refrigerate. Eat the curry within 2 days (or freeze for up to 3 months) and the cooked rice within 24 hours. Reheat until piping hot.'),
  ('bacon-carbonara', 'Bacon Carbonara', 'Silky, cheesy, peppery pasta made with just eggs, bacon and parmesan. No cream needed.', '🥓', 5, 15, 20, 2,
   1.60, 'Medium', array['dinner'], array['comfort', 'quick'], array['large pot', 'large frying pan', 'bowl', 'fork or whisk'],
   array['Bring a large pot of salted water to the boil and cook the spaghetti according to the packet.', 'In a bowl, beat the 2 eggs and 1 yolk with most of the parmesan and plenty of black pepper.', 'Meanwhile, fry the bacon (with the garlic clove if using) in a large frying pan over medium heat for 5-7 minutes until crisp and cooked through. Remove the garlic and take the pan off the heat.', 'Save a mugful of pasta water, then drain the pasta and add it straight to the bacon pan. Toss well and leave for 1 minute so it is no longer sizzling.', 'Pour in the egg mixture with a splash of pasta water and toss quickly and constantly for 1-2 minutes, off the heat, until the sauce has thickened and turned creamy as the hot pasta cooks the eggs.', 'If the sauce still looks runny, put the pan back on the lowest heat for 20-30 seconds, stirring constantly, until it thickens. Serve straight away with the rest of the parmesan.'],
   null),
  ('sausage-bean-casserole', 'Sausage & Bean Casserole', 'Smoky sausages and white beans in a thick tomato sauce. One pot, big flavour and easy to batch cook.', '🥘', 10, 35, 45, 4,
   1.70, 'Easy', array['dinner'], array['comfort', 'high-protein', 'meal-prep', 'one-pan'], array['large deep frying pan or casserole pot with a lid', 'separate chopping board for raw meat'],
   array['Heat the oil in a large deep frying pan over medium heat and brown the sausages for 8-10 minutes, turning, until coloured all over. Lift onto a board and wash your hands after handling raw sausages.', 'Add the onion and carrot (if using) to the pan and cook for 5 minutes until softened. Add the garlic and paprika for the last minute.', 'Cut each sausage into 3 pieces and return them to the pan with the canned tomatoes, beans and 200 ml water (crumble in the stock cube if using).', 'Cover and simmer for 20 minutes, stirring now and then, until the sauce is thick and the sausages are cooked through with no pink in the middle (75°C).', 'Season with salt and pepper and serve with bread for dipping.'],
   'Cool within 2 hours, refrigerate and eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('smash-burgers', 'Smash Burgers', 'Thin, crispy-edged beef patties with melty cheese in a toasted bun. Diner-style burgers at home.', '🍔', 10, 10, 20, 2,
   2.40, 'Easy', array['dinner'], array['comfort', 'high-protein', 'quick'], array['large heavy frying pan', 'sturdy metal spatula', 'baking paper', 'separate chopping board for raw meat'],
   array['Divide the mince into 4 loose balls (2 per burger). Wash your hands and the board after handling raw mince.', 'Toast the cut sides of the buns in a dry frying pan over medium heat for 1 minute, then set aside.', 'Turn the heat to high. Add 2 balls, cover each with a square of baking paper and press down hard with a spatula into thin patties. Peel off the paper and season with salt and pepper.', 'Cook for 2-3 minutes until deeply browned, then flip and cook for 1-2 minutes more until cooked through with no pink (75°C). Add the cheese to 2 patties to melt. Repeat with the other balls.', 'Stack 2 patties per bun and add onion, lettuce, tomato and sauces as you like.'],
   null),
  ('chicken-satay-noodles', 'Chicken Satay Noodles', 'Slurpable noodles and chicken in a creamy peanut sauce with a squeeze of lime. Ready in 25 minutes.', '🥜', 10, 15, 25, 2,
   2.20, 'Easy', array['dinner'], array['high-protein'], array['wok or large frying pan', 'saucepan', 'small bowl', 'separate chopping board for raw meat'],
   array['Whisk the peanut butter, soy sauce, honey, chilli flakes (if using) and juice of half the lime with 5 tbsp hot water until smooth.', 'Slice the chicken into thin strips on a separate board. Wash your hands and the board after handling raw chicken.', 'Cook the noodles in a saucepan of boiling water according to the packet, then drain.', 'Heat the oil in a wok over high heat and stir-fry the chicken for 5-6 minutes until golden and cooked through with no pink (75°C). Add the pepper for the last 2 minutes if using.', 'Lower the heat, add the noodles and satay sauce and toss for 1 minute until coated, adding a splash of water if too thick. Top with peanuts, spring onion and lime wedges.'],
   null),
  ('air-fryer-chicken-tenders', 'Air-Fryer Chicken Tenders', 'Golden, crunchy breaded chicken strips without a pan of hot oil. Dunk them in your favourite sauce.', '🍗', 15, 12, 27, 2,
   1.90, 'Easy', array['lunch', 'dinner'], array['air-fryer', 'comfort', 'high-protein'], array['2 shallow bowls', 'separate chopping board for raw meat'],
   array['Cut the chicken into strips about 2 cm thick on a separate board.', 'Beat the egg with a pinch of salt in one shallow bowl. In another, mix the breadcrumbs with the paprika and garlic powder if using.', 'Dip each strip in egg, then press into the breadcrumbs to coat. Wash your hands, the board and the bowls after handling raw chicken.', 'Preheat the air fryer to 200°C. Lay the tenders in a single layer in the basket (in batches if needed) and brush or spray lightly with oil.', 'Air fry for 10-12 minutes, turning halfway, until golden and crisp and cooked through with no pink in the middle (75°C). Serve with your dips.'],
   null),
  ('cottage-pie', 'Cottage Pie', 'Savoury beef and veg under a fluffy, golden mash topping. The ultimate cosy Sunday-night dinner.', '🥧', 15, 60, 75, 4,
   1.90, 'Medium', array['dinner'], array['comfort', 'high-protein', 'meal-prep'], array['large saucepan', 'large frying pan', 'oven dish', 'potato masher or fork', 'colander', 'separate chopping board for raw meat'],
   array['Put the potatoes in a large saucepan of cold salted water, bring to the boil and simmer for 15-20 minutes until very tender.', 'Meanwhile, heat the oil in a large frying pan over medium heat and soften the onion and carrots for 5 minutes.', 'Add the mince and fry for 6-8 minutes, breaking it up, until browned with no pink left. Wash your hands after handling raw mince.', 'Stir in the tomato puree (if using), crumble in the stock cube and add 300 ml water. Simmer for 15 minutes until thick and the meat is cooked through (75°C), adding the peas for the last 2 minutes. Season.', 'Preheat the oven to 200°C (180°C fan). Drain the potatoes and mash with the butter, milk, salt and pepper until smooth.', 'Spoon the mince into an oven dish, spread the mash on top, rough it up with a fork and sprinkle with cheese if using.', 'Bake for 20-25 minutes until golden on top and bubbling at the edges. Rest for 5 minutes before serving.'],
   'Cool within 2 hours, cover and refrigerate. Eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('rice-cooker-ginger-chicken-rice', 'Rice Cooker Ginger Chicken & Rice', 'Fragrant ginger rice and tender chicken cooked together in your rice cooker. Set it, study, then eat.', '🍚', 10, 35, 45, 2,
   1.80, 'Easy', array['dinner'], array['high-protein', 'one-pan'], array['sieve', 'bowl', 'separate chopping board for raw meat'],
   array['Cut the chicken into small pieces, about 2 cm, on a separate board and toss with 1 tbsp soy sauce, half the ginger and the garlic if using. Wash your hands and the board after handling raw chicken.', 'Rinse the rice in a sieve until the water runs clearer, then tip it into the rice cooker bowl. Add water to the usual line for this amount of white rice, crumble in the stock cube if using and stir in the rest of the ginger.', 'Spread the chicken pieces in an even single layer on top of the rice, without stirring them in. Close the lid and start the normal white rice cycle.', 'When it switches to keep warm, leave the lid closed for 10 minutes. Cut open the largest piece of chicken: it must be cooked through with no pink and the juices clear (75°C if you have a thermometer).', 'If any chicken is still pink, close the lid, run the cook cycle again for 10 minutes and check again before eating.', 'Fluff the rice with the chicken, then drizzle with the remaining soy sauce and sesame oil and scatter with spring onion.'],
   'Refrigerate leftovers within 1 hour and eat within 24 hours. Reheat until piping hot.'),
  ('tuna-pasta-bake', 'Tuna Pasta Bake', 'Cheesy, bubbling pasta bake made from cupboard staples. Makes enough for tonight and tomorrow.', '🧀', 10, 30, 40, 4,
   1.50, 'Easy', array['dinner'], array['comfort', 'high-protein', 'meal-prep'], array['large pot', 'colander', 'oven dish'],
   array['Preheat the oven to 200°C (180°C fan).', 'Cook the pasta in a large pot of boiling salted water for 2 minutes less than the packet says, then drain.', 'Mix the pasta with the passata, drained tuna, sweetcorn, oregano and garlic powder (if using) and half the cheese. Season with salt and pepper.', 'Tip into an oven dish and scatter over the rest of the cheese.', 'Bake for 20 minutes until bubbling and golden on top.'],
   'Cool within 2 hours, cover and refrigerate. Eat within 2 days, reheating until piping hot.'),
  ('microwave-steamed-salmon-greens', 'Microwave Steamed Salmon & Greens', 'Tender ginger-soy salmon steamed with broccoli and spinach in one dish. Dinner in 10 minutes, no hob needed.', '🐟', 5, 7, 12, 1,
   3.20, 'Easy', array['lunch', 'dinner'], array['fresh', 'high-protein', 'quick'], array['microwave-safe dish with a lid or plate to cover'],
   array['Put the broccoli in a microwave-safe dish with 2 tbsp water, cover and microwave on high for 2 minutes.', 'Mix the soy sauce with the ginger if using. Lay the salmon on top of the broccoli and spoon over the soy mixture.', 'Cover, leaving a small gap for steam, and microwave on high for 3-4 minutes (800 W) until the salmon is opaque all the way through and flakes easily. If not, cook in 30-second bursts.', 'Tuck the spinach in around the fish, cover and leave to stand for 1 minute so it wilts.', 'If serving with rice, heat the pouch according to the packet. Finish with a squeeze of lemon and a drizzle of sesame oil.'],
   null),
  ('stovetop-mac-and-cheese', 'Stovetop Mac & Cheese', 'Silky homemade cheese sauce clinging to every piece of macaroni. No oven, one pot.', '🧀', 5, 15, 20, 2,
   1.00, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'quick', 'vegetarian'], array['large pot', 'colander', 'whisk or wooden spoon', 'grater'],
   array['Cook the pasta in a large pot of boiling salted water for 1 minute less than the packet says, then drain and set aside.', 'Melt the butter in the same pot over medium heat, stir in the flour and cook for 1 minute, stirring constantly.', 'Gradually whisk in the milk a splash at a time to avoid lumps, then simmer gently for 3-4 minutes, stirring, until it thickens enough to coat a spoon.', 'Take the pot off the heat and stir in the grated cheese (and mustard if using) until melted and smooth.', 'Return the pasta to the sauce and stir over low heat for 1-2 minutes until hot. Season with salt and pepper and serve straight away.'],
   null),
  ('one-pan-lazy-lasagne', 'One-Pan Lazy Lasagne', 'All the layers of lasagne with none of the layering: broken pasta cooked right in a rich tomato and mushroom sauce.', '🍝', 10, 25, 35, 3,
   1.40, 'Easy', array['dinner'], array['comfort', 'one-pan', 'vegetarian'], array['large deep frying pan with a lid', 'wooden spoon'],
   array['Chop the onion and garlic. Fry the onion in the oil in a large deep frying pan over medium heat for 5 minutes until soft.', 'Add the mushrooms and cook for 5 minutes until they release their liquid, then add the garlic (and oregano if using) for 1 minute.', 'Pour in the canned tomatoes plus 400 ml water, season with salt and pepper and bring to the boil.', 'Stir in the broken pasta, making sure it is covered by the sauce. Cover and simmer for 12-15 minutes, stirring every few minutes so it does not stick, until the pasta is tender. Add a splash of water if it gets too thick.', 'Stir in the spinach if using until wilted. Scatter the mozzarella (and parmesan if using) over the top, cover and cook for 2-3 minutes until melted.'],
   null),
  ('black-bean-burgers', 'Black Bean Burgers', 'Crispy-edged, smoky bean patties made from one can. Pile them into buns or serve with salad.', '🍔', 15, 10, 25, 2,
   0.90, 'Easy', array['lunch', 'dinner'], array['budget', 'high-protein', 'vegetarian'], array['large bowl', 'fork or potato masher', 'non-stick frying pan', 'fish slice'],
   array['Tip the drained beans into a large bowl and mash with a fork, leaving some chunks for texture.', 'Add the finely chopped onion, breadcrumbs, egg, salt, pepper and the cumin and paprika if using. Mix well; if it is too wet to hold its shape, add a little more breadcrumbs.', 'Shape into 4 patties about 1.5 cm thick. Chill for 10 minutes if you have time, so they hold together better.', 'Heat the oil in a non-stick frying pan over medium heat and cook the patties for 4-5 minutes per side, flipping gently, until crisp and piping hot in the middle.', 'Serve in buns with lettuce, or with salad on the side.'],
   null),
  ('mushroom-stroganoff', 'Mushroom Stroganoff', 'Golden mushrooms in a creamy paprika sauce, ready in 20 minutes. Great over rice or pasta.', '🍄', 5, 15, 20, 2,
   2.00, 'Easy', array['dinner'], array['comfort', 'one-pan', 'quick', 'vegetarian'], array['large frying pan', 'saucepan'],
   array['If serving with rice, start cooking it in a saucepan according to the packet instructions.', 'Thinly slice the onion and garlic. Heat the oil (and butter if using) in a large frying pan over medium heat and fry the onion for 5 minutes until soft.', 'Turn the heat up to medium-high, add the mushrooms and cook for 6-8 minutes, stirring now and then, until golden and their liquid has evaporated.', 'Add the garlic and paprika and cook for 1 minute, then lower the heat and stir in the creme fraiche (and mustard if using) with a splash of water to make a sauce.', 'Simmer gently for 1-2 minutes until hot, season with salt and pepper, and serve over rice or pasta with parsley scattered on top.'],
   null),
  ('veggie-chilli', 'Veggie Chilli', 'A big pot of smoky bean chilli that tastes even better the next day. Batch-cook it on Sunday.', '🌶️', 10, 30, 40, 4,
   1.10, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'high-protein', 'meal-prep', 'vegan', 'vegetarian'], array['large pot', 'saucepan'],
   array['Chop the onion, pepper and garlic. Fry the onion and pepper in the oil in a large pot over medium heat for 6-8 minutes until soft.', 'Add the garlic, chilli powder and the cumin and paprika if using, and cook for 1 minute, stirring, until fragrant.', 'Stir in the tomato puree if using, then the canned tomatoes, drained beans and 150 ml water. Bring to the boil.', 'Simmer uncovered for 20 minutes, stirring now and then, until thick. Add the sweetcorn for the last 5 minutes if using.', 'Meanwhile, cook the rice in a saucepan according to the packet if serving. Season the chilli with salt and serve over the rice.'],
   'Cool within 2 hours, then refrigerate and eat within 2 days, or freeze for up to 3 months. Eat any cooked rice within 24 hours. Reheat until piping hot.'),
  ('roasted-cauliflower-tacos', 'Roasted Cauliflower Tacos', 'Spiced, charred cauliflower in warm tortillas with a squeeze of lime and a cool yogurt drizzle.', '🌮', 10, 25, 35, 2,
   1.60, 'Easy', array['lunch', 'dinner'], array['air-fryer', 'vegetarian'], array['baking tray', 'foil', 'large bowl'],
   array['Preheat the oven to 220°C (200°C fan).', 'Cut the cauliflower into small bite-sized florets. Toss in a large bowl with the oil, paprika, salt and the cumin and chilli powder if using.', 'Spread out on a baking tray in a single layer and roast for 20-25 minutes, turning halfway, until tender and charred at the edges.', 'For the last 5 minutes, wrap the tortillas in foil and put them in the oven to warm.', 'Mix the yogurt with a squeeze of lime and a pinch of salt if using. Fill the tortillas with cauliflower, cabbage and coriander, drizzle with the yogurt and serve with lime wedges.'],
   null),
  ('baked-feta-pasta', 'Baked Feta Pasta', 'Roast a block of feta with cherry tomatoes, then stir it into a creamy, tangy sauce. The viral classic.', '🍅', 5, 30, 35, 2,
   2.00, 'Easy', array['lunch', 'dinner'], array['comfort', 'vegetarian'], array['oven dish', 'large pot', 'colander'],
   array['Preheat the oven to 200°C (180°C fan).', 'Put the cherry tomatoes and sliced garlic in an oven dish, toss with the oil, a pinch of salt and the chilli flakes if using, then nestle the block of feta in the middle.', 'Bake for 25-30 minutes until the tomatoes have burst and the feta is soft and golden at the edges.', 'Meanwhile, cook the pasta in a large pot of boiling salted water according to the packet. Reserve a mug of pasta water, then drain.', 'Mash the feta and tomatoes together in the dish into a creamy sauce, then stir in the pasta and a splash of pasta water. Season with pepper and top with torn basil if using.'],
   null),
  ('roasted-butternut-squash-soup', 'Roasted Butternut Squash Soup', 'Velvety, sweet and golden. Roasting the squash first gives this soup a deep, caramelised flavour.', '🎃', 15, 45, 60, 3,
   0.70, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'meal-prep', 'vegetarian'], array['baking tray', 'large pot', 'vegetable peeler'],
   array['Preheat the oven to 200°C (180°C fan).', 'Peel the squash, scoop out the seeds and cut it into 3 cm chunks. Cut the onion into wedges.', 'Toss the squash, onion and whole unpeeled garlic cloves on a baking tray with the oil, salt, pepper and the cumin if using. Roast for 30-35 minutes, turning halfway, until soft and golden.', 'Squeeze the soft garlic out of its skins and tip everything into a large pot with 800 ml water (crumble in the stock cube if using). Bring to the boil and simmer for 5 minutes.', 'Let it cool for a few minutes, then blend in batches in a blender until completely smooth, filling the jug no more than halfway with hot soup.', 'Return to the pot, add a splash more water if it is too thick, season to taste and reheat until steaming. Serve with a swirl of cream and bread if you like.'],
   'Cool within 2 hours, then refrigerate and eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('stuffed-peppers', 'Stuffed Peppers', 'Sweet roasted peppers filled with cumin-spiced rice, beans and tomato, topped with bubbling cheese.', '🫑', 10, 30, 40, 2,
   1.40, 'Easy', array['lunch', 'dinner'], array['comfort', 'vegetarian'], array['oven dish', 'large bowl'],
   array['Preheat the oven to 200°C (180°C fan).', 'Halve the peppers lengthways through the stalk and remove the seeds. Brush with oil, place cut-side up in an oven dish and bake for 10 minutes to soften.', 'Meanwhile, mix the cooked rice, beans, canned tomatoes, salt and the cumin, paprika and sweetcorn if using in a large bowl. Break up any clumps of rice.', 'Pack the filling into the pepper halves and top with the grated cheese.', 'Bake for 20 minutes until the peppers are tender, the filling is piping hot all the way through and the cheese is bubbling.'],
   null),
  ('veggie-pad-thai-noodles', 'Veggie Pad Thai-Style Noodles', 'Sweet, sour and salty rice noodles with egg, crunchy veg and peanuts. Faster than a takeaway.', '🥜', 10, 10, 20, 2,
   1.40, 'Easy', array['lunch', 'dinner'], array['one-pan', 'quick', 'vegetarian'], array['wok or large frying pan', 'large heatproof bowl', 'small bowl'],
   array['Put the rice noodles in a large heatproof bowl, cover with just-boiled water and soak for 6-8 minutes (or as the packet says) until just soft. Drain and rinse with cold water.', 'In a small bowl, mix the soy sauce, sugar, the juice of half the lime and the hot sauce if using.', 'Heat 1 tbsp of the oil in a wok over high heat. Stir-fry the carrot, the white parts of the spring onions and the tofu if using for 3 minutes.', 'Push everything to one side, add the rest of the oil, crack in the eggs and scramble until fully set.', 'Add the noodles and the sauce and toss for 2 minutes until hot and coated. Serve topped with the green spring onion, peanuts, coriander and lime wedges.'],
   null),
  ('tofu-scramble', 'Tofu Scramble', 'A golden, savoury plant-based twist on scrambled eggs. Pile it onto toast for a lazy brunch.', '🍳', 5, 8, 13, 1,
   2.00, 'Easy', array['breakfast', 'lunch'], array['high-protein', 'quick', 'vegan', 'vegetarian'], array['frying pan', 'fork'],
   array['Pat the tofu dry with kitchen paper, then crumble it with a fork into small, uneven pieces.', 'Heat the oil in a frying pan over medium heat and cook the spring onion and tomato if using for 2 minutes.', 'Add the crumbled tofu, turmeric, salt, pepper and garlic powder if using. Cook for 4-5 minutes, stirring, until hot and lightly golden.', 'Stir in the spinach until wilted, then add the soy sauce and plant milk if using. Serve on toast or on its own.'],
   null),
  ('pasta-e-ceci', 'Pasta e Ceci', 'Italian pasta and chickpeas in a thick, garlicky, brothy sauce. Pure pantry comfort in one pot.', '🥣', 5, 20, 25, 2,
   0.70, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'one-pan', 'vegetarian'], array['medium pot', 'potato masher or fork'],
   array['Gently fry the garlic in the oil in a medium pot over medium-low heat for 1-2 minutes until just golden, adding the chilli flakes and herbs if using.', 'Stir in the tomato puree and cook for 1 minute, then add the drained chickpeas and 700 ml water (crumble in the stock cube if using). Bring to the boil.', 'Simmer for 5 minutes, then lightly mash about a third of the chickpeas against the side of the pot to thicken the broth.', 'Add the pasta and simmer for 10-12 minutes, stirring often so it does not stick, until the pasta is tender and the sauce is thick. Add a splash of water if needed.', 'Season with salt and pepper and serve with a drizzle of olive oil and grated parmesan if using.'],
   null),
  ('ratatouille', 'Ratatouille', 'A slow-simmered Provençal stew of aubergine, courgette and peppers. Lovely with bread, rice or pasta.', '🍆', 15, 35, 50, 4,
   1.20, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'meal-prep', 'one-pan', 'vegan', 'vegetarian'], array['large deep frying pan or pot with a lid'],
   array['Cut the aubergine, courgettes and peppers into 2 cm chunks, slice the onion and chop the garlic.', 'Heat 2 tbsp of the oil in a large deep frying pan over medium-high heat and fry the aubergine for 5-6 minutes until lightly browned. Tip it onto a plate.', 'Add the remaining oil, the onion and peppers and cook for 5 minutes, then add the courgettes and garlic for 3 minutes more.', 'Return the aubergine, add the canned tomatoes, the herbs if using and a good pinch of salt and pepper.', 'Cover and simmer gently for 20 minutes, stirring now and then, until all the vegetables are soft. Tear over basil if using and serve with bread.'],
   'Cool within 2 hours, then refrigerate and eat within 2 days, or freeze for up to 3 months. Eat cold, or reheat until piping hot.'),
  ('cheesy-broccoli-pasta', 'Cheesy Broccoli Pasta', 'Pasta and broccoli cooked in one pot, then stirred into a quick, gooey two-cheese sauce.', '🥦', 5, 12, 17, 2,
   1.40, 'Easy', array['lunch', 'dinner'], array['comfort', 'quick', 'vegetarian'], array['large pot', 'colander', 'grater'],
   array['Cut the broccoli into small florets and thinly slice the stalk.', 'Cook the pasta in a large pot of boiling salted water according to the packet, adding the broccoli for the final 4 minutes.', 'Reserve a mug of the cooking water, then drain the pasta and broccoli.', 'Return the pot to low heat and add the cream cheese, garlic if using and about 100 ml of the reserved water. Stir until smooth.', 'Add the pasta, broccoli and grated cheese and stir until the cheese melts into a glossy sauce, adding more water if needed. Season with pepper and chilli flakes if using.'],
   null),
  ('patatas-bravas', 'Patatas Bravas', 'Crispy roast potatoes with a smoky, spicy tomato sauce, just like at your favourite tapas bar.', '🥔', 10, 40, 50, 2,
   0.70, 'Easy', array['lunch', 'dinner', 'snack'], array['air-fryer', 'budget', 'spicy', 'vegetarian'], array['baking tray', 'small saucepan'],
   array['Preheat the oven to 220°C (200°C fan).', 'Cut the potatoes into 2-3 cm cubes (no need to peel). Toss on a baking tray with 2 tbsp of the oil, 1 tsp of the paprika and a good pinch of salt.', 'Roast for 35-40 minutes, turning halfway, until golden, crisp and tender inside.', 'Meanwhile, gently fry the chopped garlic in the remaining oil in a small saucepan for 1 minute. Add the rest of the paprika and the chilli flakes if using, then the canned tomatoes.', 'Simmer for 10 minutes until thick, adding a pinch of sugar and salt to taste. Mash or stir until fairly smooth.', 'Pile the potatoes onto a plate, spoon the bravas sauce over and add dollops of garlic mayonnaise if you like.'],
   null),
  ('halloumi-veg-traybake', 'Halloumi & Veg Traybake', 'Squeaky, golden halloumi on a tray of sweet roasted peppers, courgette and tomatoes. Almost no washing up.', '🧀', 10, 35, 45, 2,
   2.50, 'Easy', array['dinner'], array['high-protein', 'one-pan', 'vegetarian'], array['large baking tray'],
   array['Preheat the oven to 200°C (180°C fan).', 'Cut the courgette and peppers into chunks and the onion into wedges. Toss on a large baking tray with the oil, oregano if using, a little salt and plenty of pepper.', 'Roast for 20 minutes until starting to soften.', 'Add the cherry tomatoes and lay the halloumi slices on top of the vegetables. Roast for 12-15 minutes more until the halloumi is golden at the edges and the vegetables are tender.', 'Squeeze over the lemon if using and serve straight from the tray, with pitta if you like.'],
   null),
  ('lentil-bolognese', 'Lentil Bolognese', 'A rich, slow-tasting tomato and lentil ragù that costs pennies a portion and freezes perfectly.', '🍝', 10, 35, 45, 4,
   0.80, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'high-protein', 'meal-prep', 'vegan', 'vegetarian'], array['large pot', 'second pot', 'colander', 'grater'],
   array['Finely chop the onion, garlic and celery if using, and grate the carrots.', 'Heat the oil in a large pot over medium heat and fry the onion, carrot and celery for 7-8 minutes until soft. Add the garlic, herbs and tomato puree if using and cook for 1 minute.', 'Add the rinsed lentils, canned tomatoes and 500 ml water (crumble in the stock cube if using). Bring to the boil.', 'Simmer for 20-25 minutes, stirring often so it does not catch, until the lentils are soft and the sauce is thick. Add a splash of water if it gets too dry, and season with salt and pepper.', 'Meanwhile, cook the pasta in a second pot of boiling salted water according to the packet, then drain and serve topped with the sauce.'],
   'Cool the sauce within 2 hours, then refrigerate and eat within 2 days, or freeze for up to 3 months. Cook pasta fresh if you can, and reheat the sauce until piping hot.'),
  ('crispy-air-fryer-tofu-rice', 'Crispy Air-Fryer Tofu & Rice', 'Golden, crunchy tofu cubes tossed in a sticky soy glaze and served over fluffy rice.', '🍚', 10, 20, 30, 2,
   1.80, 'Easy', array['lunch', 'dinner'], array['air-fryer', 'high-protein', 'vegan', 'vegetarian'], array['saucepan', 'large bowl', 'small bowl', 'kitchen paper'],
   array['Cook the rice in a saucepan according to the packet instructions.', 'Drain the tofu, wrap it in kitchen paper and press under something heavy for 10 minutes to remove excess water. Cut into 2 cm cubes.', 'In a large bowl, toss the tofu with the oil and 1 tbsp of the soy sauce, then sprinkle over the flour and garlic powder if using and toss until evenly coated.', 'Cook in the air fryer at 200°C for 12-15 minutes, shaking the basket halfway, until golden and crisp.', 'Mix the remaining soy sauce with the sweet chilli sauce if using, and toss with the hot tofu. Serve over the rice with spring onion and sesame seeds.'],
   null),
  ('vegetable-paella-style-rice', 'Vegetable Paella-Style Rice', 'Smoky, golden saffron-style rice packed with peppers, peas and green beans, cooked in one wide pan.', '🥘', 10, 30, 40, 3,
   0.80, 'Medium', array['lunch', 'dinner'], array['budget', 'one-pan', 'vegan', 'vegetarian'], array['wide frying pan or paella pan', 'foil or a clean tea towel'],
   array['Dissolve the stock cube in 700 ml boiling water. Chop the onion, pepper and garlic.', 'Heat the oil in a wide frying pan over medium heat and fry the onion, pepper and green beans if using for 6-7 minutes until soft.', 'Add the garlic and grated tomato if using and cook for 2 minutes, then stir in the paprika, turmeric and rice for 1 minute to coat.', 'Pour in the hot stock, stir once to spread the rice evenly and season with salt. Simmer without stirring for 15 minutes.', 'Scatter over the peas, then cook for 5 more minutes until the liquid is absorbed and the rice is tender. If the rice is still firm, add a splash of hot water.', 'Take off the heat, cover with foil or a clean tea towel and rest for 5 minutes. Serve with lemon wedges.'],
   null),
  ('huevos-rancheros', 'Huevos Rancheros', 'Fried eggs on warm tortillas with a quick spiced tomato sauce. A brunch that wakes you up.', '🍳', 5, 15, 20, 1,
   1.30, 'Easy', array['breakfast', 'lunch'], array['quick', 'spicy', 'vegetarian'], array['frying pan', 'small saucepan'],
   array['Fry the onion in half the oil in a small saucepan over medium heat for 4 minutes. Add the garlic, chilli powder and cumin if using for 1 minute.', 'Add the canned tomatoes and a pinch of salt and simmer for 6-8 minutes until thick. If using beans, warm them in the sauce for the last 3 minutes.', 'Meanwhile, warm the tortillas one at a time in a dry frying pan for 30 seconds per side, then keep them wrapped in a clean tea towel.', 'Add the remaining oil to the frying pan and fry the eggs over medium heat for 3-4 minutes until the whites are completely set.', 'Put the tortillas on a plate, spoon over the sauce and top each with a fried egg. Finish with avocado, coriander and cheese if using.'],
   null),
  ('aubergine-chickpea-stew', 'Aubergine & Chickpea Stew', 'Silky aubergine and chickpeas simmered in a warmly spiced tomato sauce. Even better the next day.', '🍆', 10, 30, 40, 3,
   1.20, 'Easy', array['lunch', 'dinner'], array['budget', 'comfort', 'meal-prep', 'one-pan', 'vegan', 'vegetarian'], array['large deep frying pan or pot with a lid'],
   array['Cut the aubergines into 2-3 cm chunks and chop the onion and garlic.', 'Heat 2 tbsp of the oil in a large deep frying pan over medium-high heat and fry the aubergine with a pinch of salt for 8 minutes, turning, until browned on most sides.', 'Add the remaining oil and the onion and cook for 5 minutes, then stir in the garlic, cumin and the paprika and cinnamon if using for 1 minute.', 'Add the canned tomatoes, chickpeas and 150 ml water. Cover and simmer for 15 minutes, stirring now and then, until the aubergine is meltingly soft.', 'Stir in the spinach if using until wilted, season with salt and finish with coriander. Serve with bread.'],
   'Cool within 2 hours, then refrigerate and eat within 2 days, or freeze for up to 3 months. Reheat until piping hot.'),
  ('coconut-curry-noodle-soup', 'Coconut Curry Noodle Soup', 'A big, slurpable bowl of noodles in a fragrant coconut and red curry broth, ready in 20 minutes.', '🍜', 5, 15, 20, 2,
   1.80, 'Easy', array['lunch', 'dinner'], array['comfort', 'quick', 'spicy', 'vegan', 'vegetarian'], array['large saucepan'],
   array['Heat the oil in a large saucepan over medium heat and fry the curry paste (and ginger if using) for 1 minute until fragrant.', 'Stir in the coconut milk, 500 ml water and the crumbled stock cube. Bring to the boil, then simmer for 5 minutes.', 'Add the noodles and tofu if using and simmer for 3-5 minutes, or as the packet says, until the noodles are tender.', 'Add the pak choi if using for the final 2 minutes until just wilted.', 'Season with the juice of half the lime and soy sauce to taste. Ladle into bowls and top with spring onion, coriander and lime wedges.'],
   null),
  ('cheesy-garlic-bread', 'Cheesy Garlic Bread', 'Crisp baguette slathered in garlic butter and topped with stretchy melted mozzarella. Perfect for sharing.', '🥖', 5, 12, 17, 2,
   1.00, 'Easy', array['snack', 'dinner'], array['air-fryer', 'budget', 'comfort', 'quick', 'vegetarian'], array['baking tray', 'small bowl', 'bread knife'],
   array['Preheat the oven to 200°C (180°C fan).', 'Mash the softened butter with the crushed garlic and parsley if using in a small bowl.', 'Cut the baguette in half lengthways and spread the garlic butter right to the edges. Top with the mozzarella and chilli flakes if using.', 'Place on a baking tray and bake for 10-12 minutes until the edges are crisp and the cheese is melted and golden. Cut into slices and serve hot.'],
   null),
  ('creamy-rice-pudding', 'Creamy Rice Pudding', 'Slow-simmered, silky vanilla rice pudding made in a saucepan. Warm or cold, it''s a hug in a bowl.', '🍮', 2, 35, 37, 3,
   0.30, 'Easy', array['snack'], array['budget', 'comfort', 'vegetarian'], array['heavy-based saucepan', 'wooden spoon'],
   array['Put the rice, milk, sugar, a pinch of salt and the lemon peel if using in a heavy-based saucepan.', 'Bring slowly to the boil over medium heat, stirring so the rice does not stick to the bottom.', 'Turn the heat down to low and simmer gently for 30-35 minutes, stirring often, until the rice is completely tender and the pudding is thick and creamy. Add a splash more milk if it gets too thick.', 'Remove the lemon peel and stir in the vanilla and butter if using. Serve warm or cold, dusted with cinnamon.'],
   'Cool quickly (within 1 hour), then refrigerate and eat within 24 hours. Eat cold, or reheat until piping hot.')
on conflict (slug) do update
  set title = excluded.title,
      description = excluded.description,
      emoji = excluded.emoji,
      prep_minutes = excluded.prep_minutes,
      cook_minutes = excluded.cook_minutes,
      total_minutes = excluded.total_minutes,
      servings = excluded.servings,
      estimated_cost_per_serving_eur = excluded.estimated_cost_per_serving_eur,
      difficulty = excluded.difficulty,
      meal_types = excluded.meal_types,
      tags = excluded.tags,
      tools = excluded.tools,
      instructions = excluded.instructions,
      storage_note = excluded.storage_note;

-- Rebuild ingredient links for seeded recipes
